-- =====================================================================
-- WLF Electrical Solution v2.5.0
--  * User Management: change history (who changed Name, ID, Section, type,
--    status or options, and when). Super Admin only.
--  * Technical Support: old-request colours (yellow after 2 days, red after
--    3 days by default; Super Admin can change the days).
--  * Push notifications: new access request -> Super Admins; forwarded
--    support request -> the receiving R&I user. Needs the wlf-push Edge
--    Function (see the guide). Keys are created by the function itself.
--  * Troubleshooting in Bangla (MOT and NICE3000+), from the Bangla manuals.
--  * R&I Activity status "Canceled" -> "Cancelled".
-- Run in Supabase > SQL Editor after v2.4.1 (UPDATE_V240.sql). Safe to run
-- twice. Back up first. If Supabase shows an RLS warning, choose
-- "Run without RLS": every new table here enables RLS itself.
-- =====================================================================
begin;

do $pre$ begin
  if to_regprocedure('wlf_private.rpc_before_v240(text,jsonb)') is null
     or to_regclass('public.wlf_document_folders') is null then
    raise exception 'STOP: apply UPDATE_V240.sql (v2.4.x) first. Nothing was changed.';
  end if;
end $pre$;

-- ---------------------------------------------------------------- change history
create table if not exists wlf_private.access_log(
  id bigint generated always as identity primary key,
  at timestamptz not null default now(),
  actor uuid,
  target uuid not null,
  changes jsonb not null
);
create index if not exists access_log_target_idx on wlf_private.access_log(target, at desc);
alter table wlf_private.access_log enable row level security;
revoke all on wlf_private.access_log from public, anon, authenticated;

-- ---------------------------------------------------------------- push notifications
create table if not exists wlf_private.push_keys(
  id integer primary key check (id=1),
  public_key text not null,
  private_key text not null,
  created_at timestamptz not null default now()
);
create table if not exists wlf_private.push_subscriptions(
  endpoint text primary key check (endpoint ~ '^https://' and length(endpoint)<=1000),
  profile uuid not null references public.wlf_profiles(id) on delete cascade,
  p256dh text not null check (length(p256dh) between 20 and 200),
  auth text not null check (length(auth) between 8 and 100),
  device text not null default '',
  created_at timestamptz not null default now()
);
create index if not exists push_subscriptions_profile_idx on wlf_private.push_subscriptions(profile);
create table if not exists wlf_private.push_outbox(
  id bigint generated always as identity primary key,
  profile uuid not null references public.wlf_profiles(id) on delete cascade,
  title text not null,
  body text not null,
  url text not null default './',
  created_at timestamptz not null default now(),
  attempts integer not null default 0,
  sent_at timestamptz
);
create index if not exists push_outbox_pending_idx on wlf_private.push_outbox(id) where sent_at is null;
alter table wlf_private.push_keys enable row level security;
alter table wlf_private.push_subscriptions enable row level security;
alter table wlf_private.push_outbox enable row level security;
revoke all on wlf_private.push_keys, wlf_private.push_subscriptions, wlf_private.push_outbox from public, anon, authenticated;

create or replace function wlf_private.push_enqueue(target uuid, p_title text, p_body text, p_url text default './')
returns void language sql security definer set search_path='' as $$
  insert into wlf_private.push_outbox(profile,title,body,url)
  select target, left(p_title,120), left(p_body,300), left(coalesce(p_url,'./'),300)
  where exists(select 1 from wlf_private.push_subscriptions s where s.profile=target)
$$;

-- New access request -> every approved Super Admin
create or replace function wlf_private.push_new_request() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  if new.status='Pending' then
    perform wlf_private.push_enqueue(p.id, 'New access request',
      coalesce(nullif(new.name,''),new.email)
        ||case when coalesce(new.employee_id,'')<>'' then ' ('||new.employee_id||')' else '' end
        ||case when coalesce(new.section,'')<>'' then ' · '||new.section else '' end,
      './#users')
    from public.wlf_profiles p where p.role='Super Admin' and p.status='Approved' and p.auth_user_id is not null;
  end if;
  return new;
end
$$;
drop trigger if exists wlf_push_new_request on public.wlf_profiles;
create trigger wlf_push_new_request after insert on public.wlf_profiles for each row execute function wlf_private.push_new_request();

-- Service API for the wlf-push Edge Function (service role only)
create or replace function public.wlf_push_service(action text, payload jsonb default '{}'::jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare k wlf_private.push_keys; result jsonb;
begin
  if action='keys' then
    if coalesce(payload->>'publicKey','')<>'' and coalesce(payload->>'privateKey','')<>'' then
      insert into wlf_private.push_keys(id,public_key,private_key) values(1,payload->>'publicKey',payload->>'privateKey') on conflict(id) do nothing;
    end if;
    select * into k from wlf_private.push_keys where id=1;
    return case when k.id is null then null else jsonb_build_object('publicKey',k.public_key,'privateKey',k.private_key) end;
  elsif action='claim' then
    with picked as (
      select id from wlf_private.push_outbox
       where sent_at is null and attempts<5 and created_at>now()-interval '3 days'
       order by id limit 50 for update skip locked),
    upd as (update wlf_private.push_outbox o set attempts=o.attempts+1 from picked where o.id=picked.id returning o.*)
    select coalesce(jsonb_agg(jsonb_build_object('id',u.id,'title',u.title,'body',u.body,'url',u.url,
      'subscriptions',coalesce((select jsonb_agg(jsonb_build_object('endpoint',s.endpoint,'p256dh',s.p256dh,'auth',s.auth))
        from wlf_private.push_subscriptions s where s.profile=u.profile),'[]'::jsonb)) order by u.id),'[]'::jsonb)
      into result from upd u;
    return result;
  elsif action='done' then
    update wlf_private.push_outbox set sent_at=now()
     where id in (select jsonb_array_elements_text(coalesce(payload->'ids','[]'::jsonb))::bigint);
    return 'true';
  elsif action='gone' then
    delete from wlf_private.push_subscriptions
     where endpoint in (select jsonb_array_elements_text(coalesce(payload->'endpoints','[]'::jsonb)));
    return 'true';
  end if;
  raise exception 'Unsupported push action';
end
$$;
revoke all on function public.wlf_push_service(text,jsonb) from public, anon, authenticated;
grant execute on function public.wlf_push_service(text,jsonb) to service_role;

-- ---------------------------------------------------------------- old-request colours
insert into public.wlf_settings(key,value) values ('supportAging','{"yellowDays":2,"redDays":3}'::jsonb)
on conflict (key) do nothing;

-- ---------------------------------------------------------------- Cancelled spelling
update public.wlf_ri_categories set schema=replace(schema::text,'"Canceled"','"Cancelled"')::jsonb, revision=revision+1
 where schema::text like '%"Canceled"%';
update public.wlf_ri_entries set
  status=case when status='Canceled' then 'Cancelled' else status end,
  values=replace(values::text,'"Canceled"','"Cancelled"')::jsonb,
  form_schema=replace(form_schema::text,'"Canceled"','"Cancelled"')::jsonb
 where status='Canceled' or values::text like '%"Canceled"%' or form_schema::text like '%"Canceled"%';

-- ---------------------------------------------------------------- Troubleshooting in Bangla
-- Each entry gets content.bn {description, conditions, solution[], subcodes[]}.
-- English stays unchanged; the app falls back to English where Bangla is missing.
create temp table wlf_tb_bn(id text primary key, bn jsonb not null) on commit drop;
insert into wlf_tb_bn(id,bn) values
('mot-er01','{"description":"Parameter (সেটিং মান) পড়া যায়নি। Checksum (ডেটা যাচাইয়ের সংখ্যা) ভুল।","conditions":"Hardware fault।","solution":["Walton Technical Support-এর সাথে যোগাযোগ করুন।"]}'::jsonb),
('mot-er02','{"description":"Parameter লেখা যায়নি। Verify error।","conditions":"Hardware fault।","solution":["Walton Technical Support-এর সাথে যোগাযোগ করুন।"]}'::jsonb),
('mot-er03','{"description":"Parameter-গুলো নতুন version দিয়ে লেখা হয়েছিল। কিছু parameter হারিয়ে যাবে।","conditions":"পুরোনো version-এ downgrade করলে, যে function ও parameter পুরোনো version-এ নেই কিন্তু up-to-date version-এ আছে, downgrade-এর পর সেগুলোর মান মুছে যাবে।","solution":["MOT (লিফট কন্ট্রোলার/ড্রাইভ ইউনিট)-এর নতুন/up-to-date version-এ bug fix, software enhancement, নতুন feature ও function এবং আচরণগত পরিবর্তন ও উন্নতি থাকে। পুরোনো version ইনস্টল করা সত্যিই প্রয়োজন কি না ভেবে দেখুন।"]}'::jsonb),
('mot-er04','{"description":"ENCA board (এনকোডার ইন্টারফেস বোর্ড)-এর সাথে সংযোগ নেই।","conditions":"MOT 1 সেকেন্ডের বেশি সময় ENCA board-এর সাথে communicate করতে না পারলে এই error দেয়।","solution":["Encoder (ঘূর্ণন অবস্থান সেন্সর)-এর সংযোগ পরীক্ষা করুন। সংযোগ ভুল হতে পারে, অথবা encoder supply-তে সমস্যা থাকতে পারে।","MOT ও ENCA board-এর মধ্যকার flat cable পরীক্ষা করুন। এটি খুলে যেতে বা ক্ষতিগ্রস্ত হতে পারে।","“Encode type [P0520]” ও “Motor type [P0229]” parameter পরীক্ষা করুন। Synchronous motor-এর সাথে ব্যবহৃত ENCA board-এ এই error আসে। Synchronous motor ব্যবহার করলে system-এ ENCA board আছে কি না নিশ্চিত করুন। Asynchronous motor ব্যবহার করার পরও এই error এলে “Motor type [P0229]” ভুলক্রমে “Synchronous” সিলেক্ট করা হয়ে থাকতে পারে।","ENCA board ত্রুটিপূর্ণ হতে পারে।"]}'::jsonb),
('mot-er05','{"description":"DIP-switch (ছোট কনফিগারেশন সুইচ) configuration ভুল অথবা পড়া যায়নি।","conditions":"Hardware fault।","solution":["Walton Technical Support-এর সাথে যোগাযোগ করুন।"]}'::jsonb),
('mot-er06','{"description":"Encoder-এর একটি channel বিচ্ছিন্ন।","conditions":"ENCA board থেকে 1 সেকেন্ড কোনো data না এলে এই error হয়।","solution":["MOT ও ENCA board-এর মধ্যকার flat cable পরীক্ষা করুন। Encoder-এর সংযোগ ঠিকমতো করা আছে কি না নিশ্চিত করুন।"]}'::jsonb),
('mot-er07','{"description":"Current driver limit ছাড়িয়েছে।","conditions":"Motor current “Motor overcurrent limit” [P0429] parameter-এ সেট করা IPM (ইন্টেলিজেন্ট পাওয়ার মডিউল) module-এর সর্বোচ্চ current-এর শতাংশ মান ছাড়ালে এই error হয়।","solution":["MOT class current-এর মান motor-এর জন্য উপযুক্ত কি না নিশ্চিত করুন।","Car আটকে থাকতে পারে (car shoe খুব টাইট), motor brake সম্পূর্ণ খোলেনি এমনও হতে পারে।","Error দুই দিকেই হচ্ছে কি না দেখুন। শুধু এক দিকে হলে counterweight (ভারসাম্য ওজন)-এর balance ঠিক নেই; তখন counterweight balance পরীক্ষা করুন।","Geared (asynchronous) motor-এর ক্ষেত্রে “Nominal slip frequency” [P0603] ও “No-load current” [P0430] parameter ভুল সেট করা হয়ে থাকতে পারে।","Current ও speed PID (প্রোপোরশনাল-ইন্টিগ্রাল-ডেরিভেটিভ কন্ট্রোল) gain-এর মান খুব বেশি হতে পারে।","Motor cable-এর cross section current-এর জন্য উপযুক্ত কি না নিশ্চিত করুন।","MOT-এর সর্বশেষ firmware (ডিভাইসের ভেতরের সফটওয়্যার) ইনস্টল করা আছে কি না নিশ্চিত করুন।"]}'::jsonb),
('mot-er08','{"description":"Current ক্রমাগত driver limit-এর কাছাকাছি ছিল।","conditions":"Motor current “Motor overcurrent error time” [P1089] parameter-এ সেট করা সময় (standard 6 সেকেন্ড) ধরে IPM module-এর সর্বোচ্চ current-এর 250% ছাড়িয়ে গেলে এই error হয়।","solution":["MOT class current-এর মান motor-এর জন্য উপযুক্ত কি না নিশ্চিত করুন।","Car আটকে থাকতে পারে (car shoe খুব টাইট), motor brake সম্পূর্ণ খোলেনি এমনও হতে পারে।","Error দুই দিকেই হচ্ছে কি না দেখুন। শুধু এক দিকে হলে counterweight-এর balance ঠিক নেই; তখন counterweight balance পরীক্ষা করুন।","Geared (asynchronous) motor-এর ক্ষেত্রে “Nominal slip frequency” [P0603] ও “No-load current” [P0430] parameter ভুল সেট করা হয়ে থাকতে পারে।","Current ও speed PID gain-এর মান খুব বেশি হতে পারে।","Motor cable-এর cross section current-এর জন্য উপযুক্ত কি না নিশ্চিত করুন।"]}'::jsonb),
('mot-er09','{"description":"Motor বা control cabinet overheat হয়েছে।","conditions":"T1 – T2 input short circuit না থাকলে এই error হয়। MOT, T1 ও T2 input-এ সিরিজে সংযুক্ত panel, motor ও brake resistor (ব্রেকিং রোধ) PTC (তাপমাত্রা-সংবেদনশীল রোধক) পরীক্ষা করে। যেকোনো কারণে এই circuit খুলে গেলে এই error দেয়।","solution":["Motor বা panel-এর temperature খুব বেশি হতে পারে। Cooling fan পরীক্ষা করুন।","Motor, panel ও brake resistor-এর PTC এবং তাদের সংযোগ পরীক্ষা করুন।","MOT-এর T1 ও T2 input স্বাভাবিকভাবে কাজ করছে কি না দেখুন; T1 ও T2 short circuit থাকতে হবে।"]}'::jsonb),
('mot-er10','{"description":"Main contactor (বৈদ্যুতিক সুইচিং ডিভাইস) drop হওয়া শনাক্ত করা যায়নি।","conditions":"Main contactor ও brake inactive থাকা অবস্থায় “(KRC) Main contactor check back” input signal 3 সেকেন্ড active না হলে এই error হয়। Main contactor relay (RP) drop হওয়ার পরও (KRC) monitoring signal থেকে main contactor-এর অবস্থা (contactor passive) যাচাই করা যায়নি। (KM1), (KM2) ও (KM3) contactor-এর “Normally closed” contact দিয়ে আসা (100) (24VDC) signal MOT-এর (KRC) signal input-এ সংযুক্ত। সব contactor passive থাকলে (KRC) signal input-এ (100) (24VDC) signal থাকতে হবে।","solution":["(KRC) line-এ KM1, KM2 ও KM3 contactor-এর auxiliary contact ত্রুটিপূর্ণ হতে পারে।","যে input-এ (KRC) signal program করা আছে সেখানে voltage drop থাকতে পারে।","Door bridging board (দরজার safety circuit (নিরাপত্তা সার্কিট) ব্রিজিং বোর্ড) (DBR) ইনস্টল করা থাকলে এবং menu থেকে board-টি “Installed” সিলেক্ট করা থাকলে, কিন্তু 140-140P-এর মধ্যকার bridge খোলা না হলে এই error হয় (door bridging board (140) – (140P)-এর মাঝে বসে)। (DBR) board ইনস্টল করা না থাকলে (140) – (140P)-এর মধ্যে bridge থাকতে হবে।","Elevator থামা অবস্থায় Handset screen থেকে (KRC) signal active কি না দেখুন।","Note (নোট): এই error কয়েকবার ঘটলে এটি permanent error হয়ে যায়। “System Tools” menu-তে “Clear permanent error” সিলেক্ট করে permanent error মুছতে হয়।"]}'::jsonb),
('mot-er11','{"description":"Main contactor pick-up হওয়া শনাক্ত করা যায়নি।","conditions":"Main contactor ও brake active থাকা অবস্থায় “(KRC) Main contactor check back” input signal 3 সেকেন্ড active থাকলে এই error হয়। Main contactor relay (RP) active থাকার পরও (KRC) monitoring signal থেকে main contactor-এর অবস্থা (contactor active) যাচাই করা যায়নি। MOT (140P)-এর পরের safety circuit monitor করতে পারে না। তাই (140P)-এর পরের কোনো contact pick-up না করলে MOT (140P) signal দেখে (RP) relay active করে, কিন্তু contactor-এ যাওয়া safety circuit সংযোগ খোলা থাকায় contactor energize হয় না এবং এই error হয়। (KM1), (KM2) ও (KM3) contactor-এর “Normally closed” contact দিয়ে আসা (100) (24VDC) signal MOT-এর (KRC) signal input-এ সংযুক্ত। সব contactor active থাকলে (car চলার সময়) (KRC) signal input-এ (1000) (0VDC) signal থাকতে হবে।","solution":["(KRC) line-এ KM1, KM2 ও KM3 contactor-এর auxiliary contact ত্রুটিপূর্ণ হতে পারে।","যে input-এ (KRC) signal program করা আছে সেখানে voltage থাকতে পারে।","Safety circuit-এ signal (140) on কিন্তু (140P) off থাকা অবস্থায় system car চালানোর চেষ্টা করলে এই error হতে পারে।","(140P)-এর পরের safety circuit contact গুলো বন্ধ আছে কি না নিশ্চিত করুন।","“Door contacts settling time” [P0053] parameter-এর মান খুব কম সেট করা থাকলে চলা শুরুর সময় (140P) signal দেখামাত্র MOT সরাসরি (RP) relay active করে। তখন door contact পুরোপুরি বন্ধ না থাকলে (এক সেকেন্ডের ভগ্নাংশের জন্য খুলে গেলে) চলা শুরুর সময় এই error হতে পারে। এটি এড়াতে সময় কমপক্ষে “0, 3” সেকেন্ড দিতে হবে।","Car চালানোর চেষ্টার সময় Handset screen-এ “MCT” signal active কিন্তু contactor pick-up না করলে SB1 SB2 button-এর সংযোগ পরীক্ষা করুন; SB1 SB2 button-এর contact conduct না করতে পারে।","Note (নোট): এই error কয়েকবার ঘটলে এটি permanent error হয়ে যায়। “System Tools” menu-তে “Clear permanent error” সিলেক্ট করে permanent error মুছতে হয়।"]}'::jsonb),
('mot-er12','{"description":"Mechanical brake-এর holding (আটকে থাকা) শনাক্ত হয়নি।","conditions":"Brake passive থাকা অবস্থায় “(BRC) Mechanical brake check back” ও “(BRC2) Mechanical brake-2 check back” signal 3 সেকেন্ড active না হলে এই error হয়। “Mechanical brake monitoring” [P0045] ও “Mechanical brake-2 monitoring” [P0800] parameter “On” থাকা অবস্থায় brake relay “(MBR) Mechanical brake”/“(MBR2) Mechanical brake-2” drop করলে, যে input-এ brake monitoring signal (BRC) ও (BRC2) program করা আছে সেখান থেকে brake বন্ধ (passive) হওয়া শনাক্ত করা যায়নি।","solution":["Elevator থামার সময় (brake passive/বন্ধ থাকলে) যে input-এ (BRC) ও (BRC2) signal program করা আছে সেখানে 24VDC থাকতে হবে। Voltage পরীক্ষা করুন।","Brake micro switch পরীক্ষা করুন। এগুলো অস্থিরভাবে কাজ করতে পারে।","“Mechanical brake monitoring” parameter “Off” করে এই error সাময়িকভাবে বন্ধ করা যায়।","Note (নোট): এটি একটি permanent error। “System Tools” menu-তে “Clear permanent error” সিলেক্ট করে এই error-এর স্থায়িত্ব মুছতে হয়।"]}'::jsonb),
('mot-er13','{"description":"Mechanical brake release হওয়া শনাক্ত হয়নি।","conditions":"Brake active থাকা অবস্থায় “(BRC) Mechanical brake check back” ও “(BRC2) Mechanical brake-2 check back” signal 3 সেকেন্ড active থাকলে এই error হয়। “Mechanical brake monitoring” [P0045] ও “Mechanical brake-2 monitoring” [P0800] parameter “On” থাকা অবস্থায় brake relay “(MBR) Mechanical brake”/“(MBR2) Mechanical brake-2” energize করলে, যে input-এ brake monitoring signal (BRC) ও (BRC2) program করা আছে সেখান থেকে brake খোলা (active) হওয়া শনাক্ত করা যায়নি।","solution":["Elevator চলার সময় (brake active/খোলা থাকলে) যে input-এ (BRC) ও (BRC2) signal program করা আছে সেখানে 0VDC থাকতে হবে। Voltage পরীক্ষা করুন।","Brake micro switch পরীক্ষা করুন। এগুলো অস্থিরভাবে কাজ করতে পারে।","“Mechanical brake monitoring” parameter “Off” করে এই error সাময়িকভাবে বন্ধ করা যায়।","Note (নোট): এটি একটি permanent error। “System Tools” menu-তে “Clear permanent error” সিলেক্ট করে এই error-এর স্থায়িত্ব মুছতে হয়।"]}'::jsonb),
('mot-er14','{"description":"DC-bus (ডিসি লিংক) voltage খুব বেশি।","conditions":"DC-bus voltage limit voltage-এর উপরে গেলে এই error হয়। DC-bus voltage MOT class-এর rated limit voltage-এর চেয়ে বেশি। MOT 380VAC-এর জন্য: 715 V MOT 220VAC-এর জন্য: 420 V","solution":["B ও P terminal-এ উপযুক্ত brake resistor সংযুক্ত আছে কি না পরীক্ষা করুন।","Mains line (প্রধান বিদ্যুৎ লাইন) voltage খুব বেশি হলে এই error হতে পারে। Mains line voltage 420V-এর উপরে নেই তা নিশ্চিত করুন।","Device প্রথমবার চালু করার সময় এই error এলে mains line voltage পরীক্ষা করুন। Mains voltage স্থিতিশীল ও সঠিক হলে device ত্রুটিপূর্ণ হতে পারে।","Motor coil-এর insulation খুব দুর্বল হলে এই error আসতে পারে। Motor coil-এর insulation পরীক্ষা করুন।","Control panel ও motor-এর grounding পরীক্ষা করতে হবে।"]}'::jsonb),
('mot-er15','{"description":"DC-bus voltage খুব কম।","conditions":"DC-bus voltage 3 সেকেন্ড ধরে limit voltage-এর নিচে থাকলে এই error হয়। Mains line voltage operation-এর মানের নিচে নামলে এই error আসে।","solution":["B ও P terminal-এ উপযুক্ত brake resistor সংযুক্ত আছে কি না পরীক্ষা করুন।","Mains line voltage খুব কম হলে এই error হতে পারে। Mains line voltage 320V-এর নিচে নেই তা নিশ্চিত করুন।","Mains voltage স্থিতিশীল ও সঠিক হলে device ত্রুটিপূর্ণ হতে পারে। Walton Technical Support-এর সাথে যোগাযোগ করুন।"]}'::jsonb),
('mot-er16','{"description":"Power-module (IPM) error রিপোর্ট করেছে।","conditions":"MOT-এর power module (IPM) error signal পাঠিয়েছে। এই signal overcurrent, overvoltage বা over-temperature থেকে আসতে পারে।","solution":["Travel-এর সময় safety circuit কেটে যেতে পারে অথবা কোনো কারণে contactor drop করতে পারে। নির্দিষ্ট কোনো ফ্লোরে error হলে সেই landing door contact পরীক্ষা করুন। বিভিন্ন ফ্লোরে হলে car door contact পরীক্ষা করুন। Contactor ত্রুটিপূর্ণ হওয়ার সম্ভাবনা থাকলে motor cable সরাসরি MOT-এর “U, V, W” output terminal-এ সংযুক্ত করে (panel bypass করে) system-এর কাজ পরীক্ষা করুন। এ ক্ষেত্রে error না এলে contactor ও সংযোগ পরীক্ষা করুন।","Elevator easy direction-এ চলার সময় (motor generator হিসেবে কাজ করে) বা ফ্লোরে অপেক্ষার সময় এই error এলে brake resistor-এর সংযোগ পরীক্ষা করতে হবে। পরীক্ষার জন্য brake resistor সরাসরি MOT-এর “B” ও “P” output terminal-এ সংযুক্ত করা যায়।","Inspection বা recall mode-এ চলার সময় চেপে রাখা (up বা down) button ছেড়ে দিলে safety circuit কেটে যায় এবং contactor হঠাৎ drop করে। এতে car সঙ্গে সঙ্গে থামে এবং কখনো কখনো MOT IPM error দেয়। এই error এড়াতে চেপে রাখা button ছাড়ার বদলে অন্য button-টিও (up বা down) চাপুন। দুটি button চাপা থাকলে car ধীর হয়ে থেমে যাবে। Car পুরোপুরি থামার পর দুটি button ছেড়ে দিতে পারেন।"]}'::jsonb),
('mot-er17','{"description":"Encoder speed reading অসামঞ্জস্যপূর্ণ।","conditions":"Encoder থেকে পাওয়া তথ্যে অস্বাভাবিক পরিবর্তন হলে এই error হয়।","solution":["Motor parameter সঠিকভাবে সেট করা আছে কি না নিশ্চিত করুন।","Motor-এ encoder-এর mounting পরীক্ষা করুন। ঘোরার সময় encoder slip করতে পারে।","Encoder-এর সংযোগ ও grounding পরীক্ষা করতে হবে।","Encoder cable AC voltage wire থেকে কমপক্ষে 10 cm দূর দিয়ে নিতে হবে।"]}'::jsonb),
('mot-er18','{"description":"Car over speed হয়েছে।","conditions":"Encoder থেকে পাওয়া speed, হিসাব করা speed-এর চেয়ে বেশি হলে এই error হয়।","solution":["Encoder-এর সংযোগ ও motor parameter পরীক্ষা করতে হবে।","Elevator-এর counterweight balance সঠিকভাবে সেট করতে হবে। Cabin-এ nominal load-এর অর্ধেক রেখে counterweight balance পরীক্ষা করা উচিত।","Safety circuit পরীক্ষা করতে হবে। Travel-এর সময় হঠাৎ safety circuit কেটে গেলে car কিছুক্ষণের জন্য accelerate করতে পারে এবং এই error হতে পারে।","Encoder-এ electromagnetic interference থাকতে পারে, যার ফলে signal বিকৃত হয়। Panel-এর grounding সংযোগ পরীক্ষা করুন।","“Incremental” encoder ব্যবহার করলে supply ঠিকভাবে সংযুক্ত কি না নিশ্চিত করুন। Encoder supply voltage 5VDC হলে 5V terminal-এ, 5-30VDC হলে 24V terminal-এ সংযুক্ত করতে হবে। “Absolute” encoder ব্যবহার করলে “Encoder offset” angle সঠিকভাবে হিসাব হয়েছে কি না নিশ্চিত করুন। Inspection-এ “auto tune (স্বয়ংক্রিয়ভাবে মোটরের বৈশিষ্ট্য শনাক্তকরণ)” process দুইবার করুন (প্রথম “auto tune”-এর পর car-কে উপরে-নিচে চালিয়ে নেওয়া ভালো) এবং “Encoder offset” angle প্রায় একই হিসাব হয়েছে কি না নিশ্চিত করুন।"]}'::jsonb),
('mot-er19','{"description":"Required speed-এ পৌঁছানো যায়নি।","conditions":"Motor 5 সেকেন্ডের মধ্যে reference speed-এ পৌঁছাতে না পারলে এই error হয়। Motor-এ প্রয়োজনীয় power দেওয়ার পরও motor কাঙ্ক্ষিত speed-এ না পৌঁছালেও এই error আসে। Encoder দিয়ে মাপা speed 5 সেকেন্ড ধরে target speed-এর 30%-এর কম থাকলে এই error হয়। Target speed 0.05 m/s-এর কম হলে এই error দেওয়া হয় না।","solution":["Motor-এর সংযোগ ঠিকভাবে করা আছে কি না এবং motor parameter সঠিক কি না পরীক্ষা করুন।","Counterweight balance পরীক্ষা করুন।","PID control setting-এ speed PID gain অপর্যাপ্ত হতে পারে। PID gain বাড়ান।","Geared (asynchronous) motor-এর ক্ষেত্রে motor-কে open loop-এ চালান। Open loop-এ error না এলে ENCI board-এর সংযোগ ও encoder direction পরীক্ষা করুন। “Encoder direction” [P0519] parameter পরিবর্তন করে তারপর আবার auto tune process করতে হবে।","Geared (asynchronous) motor-এর ক্ষেত্রে machine plate information parameter-এর অধীনে “No-load current” [P0430] parameter 20%-এ সেট করুন।","Travel-এর সময় brake সম্পূর্ণ খোলা আছে কি না পরীক্ষা করুন।","Brake contactor active থাকা অবস্থায় motor brake পরীক্ষা করতে হবে। Brake সম্পূর্ণ না খুললে MOT এই error দেবে।"]}'::jsonb),
('mot-er20','{"description":"Encoder সংযোগ ত্রুটি।","conditions":"Absolute encoder ও ENCA board-এর মধ্যে communication নেই, অথবা ENCA board থেকে ভুল তথ্য এসেছে। এই error শুধু synchronous motor-যুক্ত system-এ আসে।","solution":["Encoder ও encoder board (ENCA)-এর মধ্যকার সংযোগ পরীক্ষা করুন।","“Encoder type” [P0520] parameter সঠিকভাবে সেট করা আছে কি না নিশ্চিত করুন।"]}'::jsonb),
('mot-er21','{"description":"অন্তত একটি phase নেই।","conditions":"এক বা একাধিক phase-এ (L1, L2 বা L3) voltage নেই অথবা voltage-এর মান খুব কম।","solution":["L1, L2, L3 phase পরীক্ষা করুন।","Normal operation-এ নয়, শুধু evacuation-এর সময় এই error এলে: “Evacuation method” [P0712] “Evacuation disabled” সিলেক্ট করা থাকলে এবং MOT-এর main power বন্ধ হলে এই error হতে পারে।"]}'::jsonb),
('mot-er22','{"description":"3-Phase sequence ভুল।","conditions":"L1, L2, L3 phase প্রত্যাশিত sequence-এ নেই।","solution":["L2 phase-কে L3 বা L1-এর সাথে বদলাতে হবে।"]}'::jsonb),
('mot-er23','{"description":"24V supply voltage খুব কম।","conditions":"MOT-এর 24VDC input-এ voltage 18-19 VDC-এর নিচে নামলে এই error হয়।","solution":["MOT-এর 24VDC input মাপুন। মাপা মান 18-19 VDC-এর নিচে হলে এই error আসে। Car না চলা অবস্থায় MOT-এর input-এ 18-19 VDC পাওয়া গেলে সম্ভবত car চলা শুরু হওয়ার পর কিছু device active হয়ে current টানতে থাকায় voltage এর নিচে নেমে যায়। Car চালিয়ে voltage পরীক্ষা করুন।","Bridge rectifier-এর আগে ব্যবহৃত 24 V transformer-এর output পরীক্ষা করুন; সেখানে 19 VAC মাপা যাওয়া উচিত। 19 VAC-এর কম হলে transformer ত্রুটিপূর্ণ হতে পারে, অথবা কোনো device বেশি current টানায় 24 VDC output voltage কমে যেতে পারে। Transformer-এর বদলে SMPS (সুইচড-মোড পাওয়ার সাপ্লাই) ব্যবহার করা হলে SMPS-এর output-এ 24VDC মাপা যেতে হবে।","Power supply-র সর্বোচ্চ current output system-এর জন্য উপযুক্ত কি না পরীক্ষা করুন।","এই error থাকা অবস্থায়ও MOT এমনকি 15 VDC threshold voltage পর্যন্ত energized থাকতে পারে। তবে চলার সময় current-খরচকারী device বেশি হলে voltage আরও কমে যেতে পারে এবং system বন্ধ হয়ে যেতে পারে।"]}'::jsonb),
('mot-er24','{"description":"Car top floor level-এর উপরে চলে গিয়েছিল।","conditions":"Car top floor level-এ থাকা অবস্থায় ML2 magnetic switch (চুম্বক-সংবেদী সুইচ) door zone magnet (দরজা-অঞ্চল নির্দেশক চুম্বক) পার করলে (ML2 signal “Off” হলে) এই error হয়। এই error শনাক্ত করার সময় encoder বিবেচনা করা হয় না; শুধু signal 818, ML1 ও ML2 বিবেচনা করা হয়।","solution":["Door zone magnet-এর অবস্থান বদলে গিয়ে থাকতে পারে।","818 magnet-এর অবস্থান বদলে গিয়ে থাকতে পারে। Shaft learning (শ্যাফটের ফ্লোর তথ্য শেখানো) done অবস্থা “No” সিলেক্ট করার পর shaft learning আবার করতে হবে।","Car top floor-এ থাকলে ML1/ML2 signal-এর একটি বা দুটিই কেটে গিয়ে থাকতে পারে। Switch পরীক্ষা করুন। Switch-এর supply voltage 19VDC-এর নিচে নেই তা নিশ্চিত করুন।","Motor parameter motor plate অনুযায়ী সেট না করা হলে বা ভুল সেট করা হলে shaft ভুলভাবে learn হয়। Motor parameter পরীক্ষা করুন।"]}'::jsonb),
('mot-er25','{"description":"Car bottom floor level-এর নিচে চলে গিয়েছিল।","conditions":"Car bottom floor level-এ থাকা অবস্থায় ML1 magnetic switch door zone magnet পার করলে (ML1 signal “Off” হলে) এই error হয়। এই error শনাক্ত করার সময় encoder বিবেচনা করা হয় না; শুধু signal 817, ML1 ও ML2 বিবেচনা করা হয়।","solution":["Door zone magnet-এর অবস্থান বদলে গিয়ে থাকতে পারে।","817 magnet-এর অবস্থান বদলে গিয়ে থাকতে পারে। Shaft learning done অবস্থা “No” সিলেক্ট করার পর shaft learning আবার করতে হবে।","Car bottom floor-এ থাকলে ML1/ML2 signal-এর একটি বা দুটিই কেটে গিয়ে থাকতে পারে। Switch পরীক্ষা করুন। Switch-এর supply voltage 19VDC-এর নিচে নেই তা নিশ্চিত করুন।","Motor parameter motor plate অনুযায়ী সেট না করা হলে বা ভুল সেট করা হলে shaft ভুলভাবে learn হয়। Motor parameter পরীক্ষা করুন।"]}'::jsonb),
('mot-er26','{"description":"মোট current measurement শূন্য ছিল না।","conditions":"U, V, W current-এর vector sum 100 milliseconds ধরে শূন্য না হলে এই error হয়।","solution":["Motor cable ও motor contactor-এর সংযোগ পরীক্ষা করুন।","Motor cable-এর সংযোগ ঠিক থাকা সত্ত্বেও এই error ক্রমাগত আসলে MOT-এর current sensor-এ সমস্যা থাকতে পারে। সমস্যাটি controller-এর না motor-এর, তা বোঝার জন্য motor cable-এর অবস্থান বদলাতে হয়। “Info” menu-র “System information” screen থেকে current sensor-এর মান দেখুন। Car ফ্লোরে থামা অবস্থায় এই তিনটি current sensor-এর মান সমান থাকা উচিত। কোনোটি আলাদা হলে একটি current sensor ত্রুটিপূর্ণ হতে পারে। Elevator থামা অবস্থায় মান সমান কিন্তু চলার সময় আলাদা হলে coil insulation-এ সমস্যা থাকতে পারে। যে output-এ current-এর মান অন্যদের থেকে আলাদা, সেখানে সংযুক্ত motor cable (U, V ও W cable) অন্য একটির সাথে বদলে দিন। Cable বদলানোর পর আলাদা মানটি অন্য sensor-এ চলে গেলে সমস্যা motor-এর। আলাদা মান একই sensor-এ থাকলে sensor ত্রুটিপূর্ণ।"]}'::jsonb),
('mot-er27','{"description":"Maximum travel time ছাড়িয়েছে।","conditions":"“Maximum allowed time of travel between floors” [P0044] parameter-এ নির্ধারিত সময়ের মধ্যে car door zone magnet (ML1 ও ML2)-এ পৌঁছাতে না পারলে এই error হয়। Car door zone-এ পৌঁছানোর পর elevator “Maximum allowed time of travel between floors” [P0044]-এ নির্ধারিত সময়ের মধ্যে পরবর্তী door zone magnet (ML1 ও ML2) দেখার জন্য অপেক্ষা করে।","solution":["Car-এর চলাচলে বাধার কারণে এই error হতে পারে। Elevator পরীক্ষা করুন।","Maximum travel time motor speed অনুযায়ী সামঞ্জস্য করতে হবে।","ML1 ও ML2 magnetic switch পরীক্ষা করতে হবে। Magnetic switch ও door zone magnet-এর মধ্যকার দূরত্ব প্রায় 1 – 1.5cm হওয়া উচিত। Magnetic switch-এর সংযোগ পরীক্ষা করতে হবে।","Door zone magnet পরীক্ষা করতে হবে।","[P0044] parameter-এর সর্বোচ্চ মান 45 সেকেন্ড, যা দীর্ঘ floor distance-এর building-এর (উঁচু tower building) জন্য যথেষ্ট নাও হতে পারে। EN-81 standard অনুযায়ী এই মান 45 সেকেন্ডের বেশি হতে পারে না। এ ক্ষেত্রে shaft-এ অতিরিক্ত magnet এবং এই magnet পড়ার জন্য একটি magnetic switch থাকতে হবে, যা “(TTR) Reset max. Travel timer” signal-যুক্ত input-এ সংযুক্ত থাকবে, যাতে 45 সেকেন্ডের সময় ছাড়িয়ে না যায়।","Note (নোট): এই error আসার পর এটি মুছতে reset করতে হবে। System-কে Inspection-এ নিয়ে আবার Normal-এ ফিরিয়ে আনলে এই error মুছবে না।"]}'::jsonb),
('mot-er28','{"description":"EN signal নেই।","conditions":"Main contactor relay (RP) ও (140P) signal active থাকার পরও 3 সেকেন্ডের মধ্যে (EN) signal active না হলে এই error হয়। (EN) signal-এ 100 (24VDC) signal যে circuit দিয়ে যায়, সেটি main contactor-এর normally open contact দিয়ে যায়।","solution":["(RP) relay active হলে (contact বন্ধ হলে) main contactor-ও active হচ্ছে কি না নিশ্চিত করুন (Handset tool-এর main screen-এর “MCT” signal দেখায় main contactor relay (RP) active কি না)।","Main contactor active হওয়ার পর (EN) signal active কি না দেখুন। Main contactor active থাকলে MOT-এর (EN) input-এ 100 (24VDC) signal আসতে হবে।","System-এ door bridging board (DBR) ইনস্টল করা (available) থাকলে “Door safety circuit bridging board” [P0069] parameter “Installed” সেট আছে কি না এবং 140 ও 140P-এর মধ্যে কোনো bridge নেই কি না নিশ্চিত করুন।","System-এ door bridging board (DBR) ইনস্টল করা না থাকলে (available না থাকলে) “Door safety circuit bridging board” [P0069] parameter “Not installed” সেট আছে কি না নিশ্চিত করুন। এ ক্ষেত্রে 140 ও 140P-এর মধ্যে bridge থাকতে হবে।"]}'::jsonb),
('mot-er29','{"description":"ML1-ML2 short circuit হয়েছে।","conditions":"ML1 ও ML2 input একই সময়ে active (“ON”) অথবা বন্ধ (“OFF”) থাকলে এই error হয়। ML1 ও ML2 door zone magnet level-এ থাকা অবস্থায় একটি magnet থেকে সরে গেলে এবং 5 milliseconds-এর মধ্যে অন্যটিও magnet level-এ না থাকলে (ML1 = ML2 = 0) এই error হয়। একইভাবে ML1 ও ML2 door zone magnet level-এর বাইরে থাকা অবস্থায় একটি magnet-এর কাছে গেলে এবং 5 milliseconds-এর মধ্যে অন্যটিও magnet level-এ এলে (ML1 = ML2 = 1) এই error হয়।","solution":["ML1 ও ML2 input-এর মধ্যে short circuit আছে কি না পরীক্ষা করুন।","ML1 ও ML2 magnetic switch-এর সংযোগ পরীক্ষা করুন। হয়তো একটি signal ক্রমাগত আসছে না। ML1 ও ML2 sensor-এর supply IBC board-এর ML0 terminal-এ (100 terminal-এ নয়) সংযুক্ত করতে হবে। নইলে system আবার energize করার পরপরই এই error হবে।","Door zone magnet গুলো একদম খাড়া (vertical) আছে এবং rail-এর জোড়ার (joint) উপর বসানো নেই তা নিশ্চিত করুন। Car ফ্লোর level-এ থাকলে sensor magnet থেকে সরে যাচ্ছে না তা নিশ্চিত করুন।","Note (নোট): এটি একটি permanent error। “System Tools” menu-তে “Clear permanent error” সিলেক্ট করে এই error-এর স্থায়িত্ব মুছতে হয়।"]}'::jsonb),
('mot-er30','{"description":"ML1-ML2 sequence ভুল অথবা পড়া যায়নি।","conditions":"Car up direction-এ চলার সময় door zone magnet-এ পৌঁছে প্রথমে ML1 signal active হলে এই error হয়। একইভাবে car down direction-এ চলার সময় door zone magnet-এ পৌঁছে প্রথমে ML2 signal active হলেও এই error হয়।","solution":["ML1 ও ML2 signal-এর একটি সংযুক্ত নেই অথবা কাজ করছে না।","ML1 ও ML2 signal-এর মধ্যে short circuit আছে কি না পরীক্ষা করুন।","ML1 ও ML2 signal উল্টো সংযুক্ত (ML2 উপরের sensor-এ, ML1 নিচের sensor-এ সংযুক্ত হওয়া উচিত)।","Magnet ML1-ML2 magnetic sensor থেকে অনেক দূরে বসানো। Magnet ও switch-এর মধ্যকার দূরত্ব প্রায় 1, 5 – 2 cm হওয়া উচিত।","Rail-এ magnetization থাকতে পারে।","Car ফ্লোরে থাকলে door zone magnet-এর মাঝখান ML1 ও ML2 sensor-এর মাঝখানের সাথে একরেখায় থাকতে হবে। Mounting পরীক্ষা করুন।","Inspection-এ car চালিয়ে ML1-ML2 signal-এর সঠিক কাজ এবং door zone magnet-এর সঠিক mounting পরীক্ষা করুন। (উদাহরণ: car ধীরে উপরে যাওয়ার সময় door zone-এ পৌঁছালে প্রথমে ML2, তারপর ML1 active হওয়া উচিত; door zone ছাড়ার সময় প্রথমে ML2, তারপর ML1 off হওয়া উচিত। নিচে যাওয়ার সময় এর উল্টো হবে।)","Note (নোট): এটি একটি permanent error। “System Tools” menu-তে “Clear permanent error” সিলেক্ট করে এই error-এর স্থায়িত্ব মুছতে হয়।"]}'::jsonb),
('mot-er31','{"description":"Door বন্ধ হয়নি।","conditions":"MOT door close command পাঠানোর পর “Door normal closing time” [P0017]/[P0050] parameter-এ নির্ধারিত সময়ের শেষে door বন্ধ হওয়া শনাক্ত না হলে (140 signal active না হলে), এবং “Time to wait after photocell (দরজার ফটোসেল সেন্সর) interruption” [P0023]-এ নির্ধারিত সময় অপেক্ষার পর controller আবার door বন্ধ করার চেষ্টা করে। “Number of unjamming tries” [P0033]-এ নির্ধারিত মানে না পৌঁছানো পর্যন্ত পুনরায় বন্ধ করার চেষ্টা চলতে থাকে।","solution":["“Door-A normal closing time” [P0017] ও “Door-B normal closing time” [P0050] parameter-এ নির্ধারিত সময় door-এর প্রকৃত বন্ধ হওয়ার সময়ের চেয়ে কম হতে পারে। এ ক্ষেত্রে এই parameter-গুলোতে closing time বাড়িয়ে আবার চেষ্টা করুন।","Door বন্ধ থাকা সত্ত্বেও signal (140) active না হলে contact খারাপ থাকতে পারে। Door contact ও সংযোগ পরীক্ষা করুন।","Semi-automatic door-এ controller board-কে (K3A) বা (K3B) close output relay-এর সাথে সংযুক্ত করতে হবে, (LIR) signal output-এর সাথে নয়। (LIR) signal door close command হিসেবে ব্যবহার করা উচিত নয়।","Door limit switch সংযুক্ত না থাকলে বা system-এ না থাকলে “Door-A limit switches” [P0013] ও “Door-B limit switches” [P0020] parameter “Not used” সেট করতে হবে।"]}'::jsonb),
('mot-er32','{"description":"Door খোলেনি।","conditions":"MOT door open command দেওয়ার পরও door parameter-এর অধীনে “Door normal opening time” [P0016]/[P0049]-এ নির্ধারিত সময়ের মধ্যে door না খুললে এই error হবে।","solution":["“Door-A normal opening time” [P0016] ও “Door-B normal opening time” [P0049] parameter-এ নির্ধারিত সময় door-এর প্রকৃত খোলার সময়ের চেয়ে কম হতে পারে। এ ক্ষেত্রে এই parameter-গুলোতে opening time বাড়িয়ে আবার চেষ্টা করুন।","Door open command active হওয়ার পর door বাস্তবেও খুলছে কি না পরীক্ষা করুন।","MOT door খোলার চেষ্টা করার সময় EN 81-1 standard অনুযায়ী automatic door-এর জন্য MOT-এর (130) ও (140) LED বন্ধ হচ্ছে কি না পরীক্ষা করুন। Safety circuit-এ bridge থাকলে সেগুলো খুলে দিন।","EN 81-20 standard অনুযায়ী automatic door-এর জন্য safety circuit signal (135) ও (140) পরীক্ষা করুন। Door খোলার পর এগুলো off থাকা উচিত (120 – 130 signal-এর মধ্যে স্থায়ী bridge থাকায় signal 130 on থাকবে)। Safety circuit-এ bridge থাকলে সেগুলো খুলে দিন।"]}'::jsonb),
('mot-er33','{"description":"Door lock হয়নি।","conditions":"Door বন্ধ থাকা সত্ত্বেও signal (137) ও (140) active না হলে এই error হয়।","solution":["Inspection বা installation-এর সময় এই error এলে operation mode installation mode-এ সেট করা আছে কি না নিশ্চিত করুন।","Normal operation-এর সময় এই error এলে door বন্ধ হওয়ার পর signal (137) ও (140) পাওয়া যাচ্ছে কি না পরীক্ষা করতে হবে। না পাওয়া গেলে door contact পরীক্ষা করতে হবে।","Photocell signal MOT-এ না দিয়ে door controller board-এ সংযুক্ত থাকলে, door খোলার পর photocell signal কেটে গেলে door controller board open command দেবে, কিন্তু MOT তা জানবে না। MOT তখনও door close command দিতে থাকবে এবং door বন্ধ না হওয়ায় এই error হবে।","Signal (140) ও (140P)-এর সংযোগ উল্টো হয়ে থাকতে পারে। পরীক্ষা করুন।"]}'::jsonb),
('mot-er34','{"description":"140 on থাকা অবস্থায় 130 off। Safety circuit পরীক্ষা করুন।","conditions":"Safety circuit signal (140) on (active) কিন্তু safety circuit signal (130) off হলে এই error হয়। UCM (অনিচ্ছাকৃত কার চলাচল) test বা door pre-opening (car থামার আগেই দরজা খোলা)-এর সময় এই error দেওয়া হয় না। DBR board দ্বারা door bridge করা থাকলেও এই error দেওয়া হয় না।","solution":["Safety circuit-এর সংযোগ পরীক্ষা করুন। Landing door বন্ধ হওয়ার পর signal (130) এবং car door বন্ধ হওয়ার পর signal (140) on (active) থাকা উচিত।"]}'::jsonb),
('mot-er35','{"description":"Travel-এর সময় safety-chain (120) বিচ্ছিন্ন হয়েছে।","conditions":"“When safety chain (120) is off” [P0795] parameter “Block elevator” বা “Block until a car call” সেট থাকলে এবং elevator inspection/recall mode-এ না থাকা অবস্থায় চলার সময় safety chain (120) signal কেটে গেলে এই error দেওয়া হয়।","solution":["120 circuit পরীক্ষা করুন। 120-এর আগের door, slack rope, regulator contact এবং অন্য যেকোনো safety circuit contact (যেগুলো সরাসরি car-এর চলাচলের সাথে সম্পর্কিত) পরীক্ষা করুন।"]}'::jsonb),
('mot-er36','{"description":"Absolute encoder fault (Elgo Limax)।","conditions":"Absolute encoder parameter [(P1041) Abs.position shaft encoder settings] সঠিকভাবে সেট করা হয়নি। Elgo Limax ও MOT-এর মধ্যে communication ব্যর্থ হয়েছে। Limax over speed, UCM, ভুল direction এবং limit অতিক্রম (normal operation ও inspection limit) শনাক্ত করেছে। (Fault signal) Limax একটি internal error দিয়েছে। (Defect code)","solution":["Limax33RED + SAFEBOX অথবা Limax33CP ব্যবহার করলে “Error 36” আসার পর “Info” menu-র “Limax Status” screen পরীক্ষা করতে হবে।","MOT-Arlim-Limax-এর মধ্যকার communication status “Limax Status” screen-এ দেখা যায়। (Arlim board MOT ও Limax-এর মধ্যে communication সরবরাহ করে)","“Fault” দেখালে “Limax Status” screen-এর পরের পাতাগুলোতে কোন red box active তা খুঁজে দেখতে হবে।","“Defect” দেখালে defect code-এর অর্থ Elgo-র লেখা user manual থেকে দেখতে হবে।"]}'::jsonb),
('mot-er37','{"description":"Travel-এর সময় 140 বিচ্ছিন্ন হয়েছে।","conditions":"Travel-এর সময় signal (140) 50 milliseconds না থাকলে এই error হয়।","solution":["Door safety circuit-এর contact ও mechanism পরীক্ষা করুন।","Travel-এর সময় car door contact কেটে যেতে পারে। Car door contact পরীক্ষা করুন।","Travel-এর সময় door close signal কেটে যেতে পারে। Door ও door signal-এর সংযোগ পরীক্ষা করুন।"]}'::jsonb),
('mot-er38','{"description":"Encoder position, magnet reading থেকে অনেক আলাদা ছিল।","conditions":"Normal operation-এর সময় car door zone magnet পার হলে encoder-এর তথ্য এবং shaft learning-এর সময় শেখা তথ্য তুলনা করা হয়। পার্থক্য 15 cm-এর বেশি হলে এই error হয়।","solution":["Encoder ঠিকমতো কাজ না করতে পারে, অথবা encoder coupling slip করছে।","Shaft learning-এর পর door zone magnet-এর অবস্থান বদলে গিয়ে থাকতে পারে। মনে রাখতে হবে, যেকোনো magnet-এর অবস্থান বদলালে shaft learning আবার করতে হবে।","Rail-এর magnetization-এর কারণে magnetic switch-এ অনাকাঙ্ক্ষিত signal আসতে পারে। Inspection-এ car-কে top floor থেকে bottom floor পর্যন্ত চালিয়ে ML1 ও ML2 switch-এর কাজ পরীক্ষা করুন। Magnet না থাকা সত্ত্বেও switch active হলে rail-এর ওই অংশ পরিষ্কার করুন।"]}'::jsonb),
('mot-er39','{"description":"Door-zone magnet পাওয়া যায়নি।","conditions":"Shaft learning-এর সময় শেখা door zone magnet-এর অবস্থানের ±3 cm-এর মধ্যে car থাকা অবস্থায় ML1 বা ML2 signal-এর একটি active না থাকলে এই error হয়।","solution":["ML1 ও ML2 magnetic switch পরীক্ষা করুন।","Door zone magnet পরীক্ষা করুন। Magnet সরে গিয়ে থাকতে পারে। আবার shaft learning করুন।","Encoder ঠিকমতো কাজ না করতে পারে, অথবা encoder coupling slip করছে।"]}'::jsonb),
('mot-er40','{"description":"Earthquake sensor active হয়েছে।","conditions":"(DEP) input active হলে এই error হয়।","solution":["(DEP) signal হিসেবে যে programmable input নির্ধারিত, সেটি LOW (0 VDC) না HIGH (24 VDC) তা পরীক্ষা করুন।","Note (নোট): এটি একটি permanent error। “System Tools” menu-তে “Clear permanent error” সিলেক্ট করে এই error-এর স্থায়িত্ব মুছতে হয়। তারপর system reset করুন। System-কে Inspection-এ নিয়ে আবার Normal-এ ফিরিয়ে আনলে এই error মুছবে না।"]}'::jsonb),
('mot-er41','{"description":"817 signal যখন OFF হওয়ার কথা তখন OFF হয়নি।","conditions":"Normal operation-এর সময় encoder থেকে পাওয়া position তথ্য অনুযায়ী car 817 magnet-এর নিচে থাকলে এবং 817 signal না কাটলে এই error হয়।","solution":["817 magnet সরে গিয়ে থাকতে পারে। Magnet ঠিক করার পর shaft learning আবার করুন।","Rope অতিরিক্ত slip করলে এই error হতে পারে, কারণ তখন encoder-এর তথ্য শেখা shaft তথ্যের সাথে মিলবে না।","Note (নোট): এটি একটি permanent error। “System Tools” menu-তে “Clear permanent error” সিলেক্ট করে এই error-এর স্থায়িত্ব মুছতে হয়।"]}'::jsonb),
('mot-er42','{"description":"817 signal যখন ON হওয়ার কথা তখন ON হয়নি।","conditions":"Normal operation-এর সময় encoder থেকে পাওয়া position তথ্য অনুযায়ী car 817 magnet-এর উপরে থাকলে এবং 817 signal active না হলে এই error হয়।","solution":["817 magnet সরে গিয়ে থাকতে পারে। Magnet ঠিক করার পর shaft learning আবার করুন।","Rope অতিরিক্ত slip করলে এই error হতে পারে, কারণ তখন encoder-এর তথ্য শেখা shaft তথ্যের সাথে মিলবে না।"]}'::jsonb),
('mot-er43','{"description":"818 signal যখন OFF হওয়ার কথা তখন OFF হয়নি।","conditions":"Normal operation-এর সময় encoder থেকে পাওয়া position তথ্য অনুযায়ী car 818 magnet-এর উপরে থাকলে এবং 818 signal না কাটলে এই error হয়।","solution":["818 magnet সরে গিয়ে থাকতে পারে। Magnet ঠিক করার পর shaft learning আবার করুন।","Rope অতিরিক্ত slip করলে এই error হতে পারে, কারণ তখন encoder-এর তথ্য শেখা shaft তথ্যের সাথে মিলবে না।","Note (নোট): এটি একটি permanent error। “System Tools” menu-তে “Clear permanent error” সিলেক্ট করে এই error-এর স্থায়িত্ব মুছতে হয়।"]}'::jsonb),
('mot-er44','{"description":"818 signal যখন ON হওয়ার কথা তখন ON হয়নি।","conditions":"Normal operation-এর সময় encoder থেকে পাওয়া position তথ্য অনুযায়ী car 818 magnet-এর নিচে থাকলে এবং 818 signal active না হলে এই error হয়।","solution":["818 magnet সরে গিয়ে থাকতে পারে। Magnet ঠিক করার পর shaft learning আবার করুন।","Rope অতিরিক্ত slip করলে এই error হতে পারে, কারণ তখন encoder-এর তথ্য শেখা shaft তথ্যের সাথে মিলবে না।"]}'::jsonb),
('mot-er45','{"description":"Door limit-switch fault।","conditions":"“Door-A limit switches” [P0013] এবং/অথবা “Door-B limit switches” [P0020] parameter-এ নির্ধারিত door limit switch ঠিকমতো কাজ না করলে এই error হয়।","solution":["Door limit switch ব্যবহার না করলে parameter “Not used” সেট করতে হবে; ব্যবহার করলে wiring সঠিকভাবে করতে হবে।","HANDSET-এর basic status screen-এ যেখানে door দেখানো হয়, সেখানে door সম্পূর্ণ খোলা ও সম্পূর্ণ বন্ধ থাকার limit তথ্য নীল “I” চিহ্ন দিয়ে দেখা যায়। Door সম্পূর্ণ খোলা থাকলে door-এর সবুজ ত্রিভুজ আইকনের বাইরে door open limit তথ্য নীল “I” চিহ্নে দেখায়। Door সম্পূর্ণ বন্ধ থাকলে door-এর লাল ত্রিভুজ আইকনের ভেতরে door close limit তথ্য নীল “I” চিহ্নে দেখায়।","Limit গুলো input-এ সঠিকভাবে program করা আছে কি না পরীক্ষা করুন। Door fully-opened (IBC board PI5 input) ও fully-closed (IBC board PI6 input) input এবং input-এর contact type পরীক্ষা করতে হবে। সংশ্লিষ্ট input-এর contact type HANDSET tool-এ F2 button চেপে বদলানো যায়।"]}'::jsonb),
('mot-er47','{"description":"Brake resistor overheat হয়েছে।","conditions":"Brake resistor-এর temperature sensor দিয়ে মাপা হয় না। তবে brake resistor-এর On/Off অবস্থা ও DC-bus voltage-এর ভিত্তিতে brake resistor-এর আনুমানিক temperature সবসময় হিসাব করা হয়। এই হিসাব করা temperature নির্দিষ্ট limit-এর উপরে গেলে এই error দেওয়া হয়।","solution":["Brake resistor MOT-এর জন্য উপযুক্ত কি না পরীক্ষা করুন।","Brake resistor নির্দেশনা অনুযায়ী ইনস্টল করা এবং সঠিক বাতাস চলাচলের জন্য চার দিকেই খোলা আছে কি না নিশ্চিত করুন।"]}'::jsonb),
('mot-er48','{"description":"Heatsink overheat হয়েছে।","conditions":"MOT-এর ভেতরে IPM module ও bridge rectifier diode-এর সাথে যুক্ত refrigerant (cooling অংশ)-এর temperature একটি sensor দিয়ে monitor করা হয়। Refrigerant-এর temperature “Heatsink overheat error threshold” [P0774] parameter-এ দেওয়া মান ছাড়ালে এই error দেওয়া হয়।","solution":["Device-এর নিচের fan গুলো কাজ করছে কি না পরীক্ষা করুন।","Device বাতাস চলাচলহীন, সংকীর্ণ জায়গায় চালালে খুব গরম হয়ে যাবে। MOT যেখানে চলছে সেই জায়গার ventilation পরীক্ষা করুন।","সময়ের সাথে MOT ও তার fan-এ ধুলো জমতে পারে। এই ধুলো তাপ বিনিময়ে বাধা দিয়ে এই error ঘটাতে পারে। ধুলো থাকলে পরিষ্কার করুন।","প্রয়োজন হলে [P0774] parameter-এর temperature মান বাড়ানো যায়।"]}'::jsonb),
('mot-er49','{"description":"External error (XER1) signal active হয়েছে।","conditions":"(XER1) input signal active হলে এই error হয়।","solution":["যে programmable input-এ (XER1) signal নির্ধারিত, সেটি signal 100 (24VDC) দিয়ে trigger হলে system এই error দেবে। Input trigger হয়েছে কি না নিশ্চিত করুন। Input low (off) হওয়ার পর elevator 5 সেকেন্ডের মধ্যে normal operation-এ ফিরে যাবে।"]}'::jsonb),
('mot-er50','{"description":"External error (XER2) signal active হয়েছে।","conditions":"Car ফ্লোরে থাকা অবস্থায় (XER2) input signal active হলে এই error হয়।","solution":["যে programmable input-এ (XER2) signal নির্ধারিত, সেটি signal 100 (24VDC) দিয়ে trigger হলে system এই error দেবে। Input trigger হয়েছে কি না নিশ্চিত করুন। Input low (off) হওয়ার পর elevator 5 সেকেন্ডের মধ্যে normal operation-এ ফিরে যাবে।"]}'::jsonb),
('mot-er51','{"description":"External blocking signal (XBL1) active হয়েছে।","conditions":"(XBL1) input signal active হলে এই error হয়।","solution":["যে programmable input-এ (XBL1) signal নির্ধারিত, সেটি signal 100 (24VDC) দিয়ে trigger হলে system এই error দেবে। Input trigger হয়েছে কি না নিশ্চিত করুন। Input low (off) হওয়ার পরও elevator blocked থাকবে।","Note (নোট): Signal আর active না থাকার পর system-কে normal operation-এ ফিরিয়ে আনতে inspection key ঘুরিয়ে system-কে inspection-এ নিন, তারপর আবার normal-এ ফিরিয়ে দিন।"]}'::jsonb),
('mot-er52','{"description":"External blocking signal (XBL2) active হয়েছে।","conditions":"Car ফ্লোরে থাকা অবস্থায় (XBL2) input signal active হলে এই error হয়।","solution":["যে programmable input-এ (XBL2) signal নির্ধারিত, সেটি signal 100 (24VDC) দিয়ে trigger হলে system এই error দেবে। Input trigger হয়েছে কি না নিশ্চিত করুন। Input low (off) হওয়ার পরও elevator blocked থাকবে।","Note (নোট): Signal আর active না থাকার পর system-কে normal operation-এ ফিরিয়ে আনতে inspection key ঘুরিয়ে system-কে inspection-এ নিন, তারপর আবার normal-এ ফিরিয়ে দিন।"]}'::jsonb),
('mot-er53','{"description":"Encoder direction ভুল।","conditions":"MOT positive direction signal দেওয়ার পরও encoder থেকে negative signal এলে, অথবা এর উল্টো হলে, এই error হবে।","solution":["“Encoder direction” [P0519] parameter পরিবর্তন করে আবার চেষ্টা করুন। (Gearless machine-এর ক্ষেত্রে encoder direction বদলালে Auto-Tune process আবার করতে হবে)"]}'::jsonb),
('mot-er54','{"description":"OGD error।","conditions":"Anti-Rollback PID gain-এর মান খুব বেশি সেট করা হলে start ঝাঁকুনিযুক্ত (jerky) হবে। এ ক্ষেত্রে এই error দেওয়া হবে।","solution":["Anti-Rollback PID gain-এর মান কমান।"]}'::jsonb),
('mot-er55','{"description":"Contactor drop করেছে।","conditions":"Motor চালু হওয়ার সময়, travel-এর সময় বা থামার সময় “(EN) Main contactor active” signal active না থাকলে এই error হয়। (KM1) ও (KM2) contactor-এর “Normally open” contact দিয়ে আসা (100) (24VDC) signal (EN) signal input-এ সংযুক্ত। সব contactor active থাকলে (EN) signal input-এ (100) signal থাকতে হবে। Travel-এর সময় কোনো contactor drop করলে অথবা (EN) signal input থেকে (100) signal কেটে গেলে এই error দেওয়া হয়।","solution":["Travel-এর সময় safety circuit কেটে গিয়ে থাকতে পারে।","(EN) signal-এর সংযোগ হয়তো ঠিকভাবে wiring করা হয়নি, অথবা terminal-এ voltage drop থাকতে পারে। (EN) signal input মাপুন।","(EN) signal input-এ সংযুক্ত auxiliary contactor-এ সমস্যা থাকতে পারে। Contactor পরীক্ষা করুন।","Door pre-opening-এর সময় এই error এলে ML1-ML2 signal-এ electromagnetic noise এসে থাকতে পারে।"]}'::jsonb),
('mot-er56','{"description":"817 ও 818 একই সময়ে কেটে গেছে।","conditions":"Signal (817) ও (818) একই সময়ে কেটে গেলে এই error হয়। শুধু 2 তলার elevator-এ এই error দেওয়া হয় না।","solution":["817 ও 818 signal-এর wiring এবং তাদের magnetic switch পরীক্ষা করুন।","Travel cable-এ signal line (817) এবং/অথবা (818)-এ ছিঁড়ে যাওয়া থাকতে পারে। (817) ও (818) signal-এর জন্য travelling cable-এর spare wire ব্যবহার করুন।"]}'::jsonb),
('mot-er57','{"description":"Motor current unbalanced।","conditions":"Motor-এর এক বা দুই phase motor-কে supply না দিলে এই error হয়।","solution":["Main contactor KM1 ও KM2 পরীক্ষা করুন। পরীক্ষার জন্য motor cable সরাসরি MOT-এর motor terminal-এ সংযুক্ত করা যায়। সমস্যা থেকে গেলে MOT-এর motor output-এ অথবা motor winding-এ সমস্যা থাকতে পারে।"]}'::jsonb),
('mot-er58','{"description":"Current sensor offset fault।","conditions":"Current sensor পড়া যায় না। U, V ও W current sensor-এর offset মান 1 সেকেন্ড ধরে গ্রহণযোগ্য সর্বনিম্ন ও সর্বোচ্চ মানের মধ্যে না থাকলে এই error দেওয়া হয়।","solution":["“Info” menu-র “System information” screen থেকে current sensor-এর মান দেখুন। Car ফ্লোরে থামা অবস্থায় এই তিনটি current sensor-এর মান সমান থাকা উচিত। কোনোটি আলাদা হলে একটি current sensor ত্রুটিপূর্ণ হতে পারে। Elevator থামা অবস্থায় মান সমান কিন্তু চলার সময় আলাদা হলে coil insulation-এ সমস্যা থাকতে পারে।","সমস্যাটি controller-এর না motor-এর, তা বোঝার জন্য motor cable-এর অবস্থান বদলাতে হয়। যে output-এ current-এর মান অন্যদের থেকে আলাদা, সেখানে সংযুক্ত motor cable (U, V ও W cable) অন্য একটির সাথে বদলে দিন। Cable বদলানোর পর আলাদা মানটি অন্য sensor-এ চলে গেলে সমস্যা motor-এর। আলাদা মান একই sensor-এ থাকলে sensor ত্রুটিপূর্ণ।","Walton Technical Support-এর সাথে যোগাযোগ করুন।"]}'::jsonb),
('mot-er59','{"description":"Car ভুল direction-এ চলছে।","conditions":"Car reference speed positive থাকা অবস্থায় signal 817 active থেকে passive (on থেকে off) হলে, অথবা car reference speed negative থাকা অবস্থায় signal 818 active থেকে passive (on থেকে off) হলে এই error হয়।","solution":["Up travel-এর সময় error এলে 817 signal, down travel-এর সময় এলে 818 signal পরীক্ষা করতে হবে।","817, 818 কেটে গিয়ে থাকতে পারে অথবা short circuit থাকতে পারে।","817, 818 signal cable ছিঁড়ে থাকতে পারে।","Inspection-এ car চালিয়ে motor direction ও signal-গুলোর কাজ পরীক্ষা করুন।"]}'::jsonb),
('mot-er60','{"description":"Door bridging failure।","conditions":"Door bridging-এর সময় কোনো error শনাক্ত হলে অথবা DBR board সংক্রান্ত কোনো সমস্যা শনাক্ত হলে এই error দেওয়া হয়।","solution":["DBR board ত্রুটিপূর্ণ হতে পারে।","ML1 ও ML2 signal-এ electrical noise আসছে অথবা signal গুলো অস্থিরভাবে কাজ করছে।"]}'::jsonb),
('mot-er61','{"description":"UDI exception।","conditions":"CPU (প্রধান প্রসেসর) error।","solution":["Walton Technical Support-এর সাথে যোগাযোগ করুন।"]}'::jsonb),
('mot-er62','{"description":"Overflow exception।","conditions":"CPU error।","solution":["Walton Technical Support-এর সাথে যোগাযোগ করুন।"]}'::jsonb),
('mot-er63','{"description":"Watchdog (প্রোগ্রাম হ্যাং শনাক্তকারী টাইমার) timeout।","conditions":"CPU error।","solution":["Walton Technical Support-এর সাথে যোগাযোগ করুন।"]}'::jsonb),
('mot-er65','{"description":"DFC communication error।","conditions":"Menu থেকে “Door safety contact connections” [P1029] parameter “EN81-20 compatible” সিলেক্ট করা থাকলে এবং DFC board সংযুক্ত না থাকলে, অথবা সংযোগ থাকলেও DFC board-এর firmware up-to-date না হলে এই error দেওয়া হয়। DFC board ত্রুটিপূর্ণ কি না পরীক্ষা করুন।","solution":["DFC board-এর সংযোগ পরীক্ষা করতে হবে এবং DFC board-এর firmware up-to-date কি না নিশ্চিত হতে হবে। DFC board-এর MCU LED synchronously blink না করলে MOT software update করতে হবে এবং update process-এর সময় “DFC” board পাওয়া যাচ্ছে কি না নিশ্চিত হতে হবে। Update করতে “Tools” menu-র “Software update” screen-এ গিয়ে সর্বশেষ তারিখের (সবচেয়ে নতুন) version-এ ক্লিক করে system update করুন।"]}'::jsonb),
('mot-er66','{"description":"Door contact বা DFC board error।","conditions":"EN 81-20 standard অনুযায়ী প্রতিবার ফ্লোরে door খোলার সময় door contact-এ কোনো bridge (যা স্বাভাবিকভাবে থাকার কথা নয়) আছে কি না পরীক্ষা করা হয়। পরীক্ষার সময় DFC board কোনো অপ্রত্যাশিত signal শনাক্ত করলে (door contact signal যেখানে কাটার কথা সেখানে না কাটলে) এই error হয়।","solution":["Door type ও safety circuit-এর সংযোগ পরীক্ষা করতে হবে। নিচের table অনুযায়ী safety circuit signal গুলো সঠিকভাবে active হচ্ছে কি না পরীক্ষা করতে হবে।","দুটি door একই সাথে খুললে দুটি test করা হয়। Test-এর ফল table অনুযায়ী সঠিক না হলে system error দেবে।","EN 81-20 standard অনুযায়ী full-automatic door-এর জন্য landing A door contact 130-133-এর মধ্যে, landing B contact 133-135-এর মধ্যে, car A door contact 135-137-এর মধ্যে (IBC board-এর KA1-KA2 terminal-এ) এবং car B door contact 137-140-এর মধ্যে (IBC board-এর KB1-KB2 terminal-এ) সংযুক্ত থাকে। Door wiring পরীক্ষা করুন। System-এর প্রথম installation-এর সময় করা bridge গুলো খুলে দেওয়া হয়েছে এবং door wiring সঠিকভাবে করা হয়েছে কি না নিশ্চিত করুন। এছাড়া full-automatic door-এর জন্য safety circuit signal 120 ও 130-এর মধ্যে সবসময় একটি স্থায়ী bridge থাকে।"]}'::jsonb),
('mot-er71','{"description":"License key (dongle (লাইসেন্স কী ডিভাইস)) পাওয়া যায়নি।","conditions":"“Device Class” [P0839] parameter “Midline” সেট থাকলে এবং system-এ কোনো “Midline” বা “Highline” dongle ইনস্টল না থাকলে, অথবা parameter “Highline” সেট থাকলে এবং system-এ কোনো “Highline” dongle ইনস্টল না থাকলে এই error দেওয়া হয়।","solution":["প্রয়োজনীয় dongle ARKEL থেকে অর্ডার করার পর system-এ ইনস্টল করুন। এটি CANbus (কন্ট্রোলার যোগাযোগ বাস) line-এ সংযুক্ত করে firmware update করুন।","MOT-কে “Basic” function-এ ব্যবহার করতে চাইলে এই parameter “Basic” সেট করুন।"]}'::jsonb),
('mot-er72','{"description":"Feature সীমিত।","conditions":"“Device Class” [P0839] parameter “Basic” সেট থাকলে এবং নিচের যেকোনো অবস্থা থাকলে এই error হয়। “Number of floors” [P0002] 16-এর বেশি সেট করা হয়েছে। “Maximum travel speed” [P0135] 1.6 m/s-এর বেশি সেট করা হয়েছে। Group-এ 2টির বেশি MOT আছে। “Firefighter operation (Phase-2) enabled” [P0842] “Yes” সেট করা হয়েছে। “Priority service function” [P0890] “Enabled” সেট করা হয়েছে। “Park floor selection method” [P0942] “Park floor is selected by time zone” সেট করা হয়েছে। Fire evacuation ও firefighting setting-এ “U36 function [P0959] is set as ON”। “Device Class” [P0839] parameter “Midline” সেট থাকলে এবং নিচের যেকোনো অবস্থা থাকলে এই error হয়। “Number of floors” [P0002] 24-এর বেশি সেট করা হয়েছে। “Maximum travel speed” [P0135] 2.5 m/s-এর বেশি সেট করা হয়েছে। কোনো license code দেওয়া না হলে বা [P1255] “CANbus protocol license code” parameter-এ license code ভুল দেওয়া হলে, অথচ “CANbus protocol” [P1254] “Protocol OEM” সেট করা থাকলে। MODBUS license code ভুল বা অনুপস্থিত থাকা অবস্থায় Serial communication port-এ read বা write request পাঠানো হলে।","solution":["উপরে উল্লিখিত function গুলো ব্যবহার করতে চাইলে এবং system-এ MOT Dongle ইনস্টল করা থাকলে [P0839] parameter dongle অনুযায়ী সেট করুন। আপনার “Basic” model MOT থাকলে এবং উপরের কোনো function ব্যবহার করতে চাইলে Walton Technical Support-এর সাথে যোগাযোগ করুন।"]}'::jsonb),
('mot-er73','{"description":"Shaft-এর ভেতরে প্রবেশ শনাক্ত হয়েছে।","conditions":"Shaft entry protection active থাকলে, car যে ফ্লোরে আছে সেটি ছাড়া অন্য কোনো ফ্লোর থেকে “(SPR*) Shaft entry protection switch Floor-*” signal এলে এই error দেওয়া হয় (door বন্ধ থাকলে স্বাভাবিকভাবে কোনো signal থাকার কথা নয়। Shaft-এ প্রবেশ শনাক্ত হলে signal আসে)।","solution":["Door contact এবং SPR signal-এর signal status পরীক্ষা করুন (SPR signal গুলো “Input/output States by Function” menu থেকে পরীক্ষা করতে হবে)।","Note (নোট): এটি একটি permanent error। “System Tools” menu-তে “Clear permanent error” সিলেক্ট করে এই error-এর স্থায়িত্ব মুছতে হয়।"]}'::jsonb),
('mot-er74','{"description":"Encoder offset angle পাওয়া যায়নি।","conditions":"Synchronous motor (gearless)-এর সাথে “incremental encoder” ব্যবহার করলে এবং Auto-Tune process-এর সময় encoder “offset angle” পাওয়া না গেলে এই error হয়।","solution":["Encoder-এর সংযোগ electrical diagram অনুযায়ী পরীক্ষা করে ঠিক করতে হবে। বিশেষ করে Z channel পরীক্ষা করতে হবে।","“Absolute encoder” ব্যবহার করলে encoder parameter পরীক্ষা করতে হবে।"]}'::jsonb),
('mot-er75','{"description":"CML feedback error।","conditions":"Motor brake UCM-এর সমাধান হিসেবে ব্যবহার না করা হলে কখনো কখনো car-এর নিচে একটি বিশেষ coil ব্যবহার করা হয়। Car চলার আগে সেই coil energize করা হয় এবং car থামলে de-energize করা হয়। Car থামলে CML input high এবং car চললে low থাকে। এই device যে (CMLC) signal (input) দিয়ে monitor করা হয়, তাতে অস্থির কাজ থাকলে এই error হয়।","solution":["Car চলার সময় যে input-এ (CMLC) signal program করা আছে সেখানে 0VDC মাপা যাওয়া উচিত; car ফ্লোরে থাকলে input voltage 24VDC মাপা যাওয়া উচিত।","CML device ব্যবহার না করলে “Car movement lock (CML) monitoring” [P1056] parameter “Off” সেট করে monitoring বন্ধ করা যায়।","Note (নোট): এটি একটি permanent error। “System Tools” menu-তে “Clear permanent error” সিলেক্ট করে এই error-এর স্থায়িত্ব মুছতে হয়।"]}'::jsonb),
('mot-er76','{"description":"Shaft protection reset key active আছে।","conditions":"EN 81-21 application-এ ব্যবহৃত shaft protection reset input (DOMRS) 60 সেকেন্ডের বেশি সময় ধরে ক্রমাগত active থাকলে এই error দেওয়া হয়।","solution":["এই input শুধু reset process-এর সময় active করা উচিত। তারপর এই input de-energize করতে হবে। যে input-এ (DOMRS) signal নির্ধারিত, সেটি ক্রমাগত energized নেই তা পরীক্ষা করুন।"]}'::jsonb),
('mot-er79','{"description":"Current motor limit ছাড়িয়েছে।","conditions":"Motor-এ পাঠানো current-এর মান “Nominal motor current” [P0159] parameter-এ নির্ধারিত মান ছাড়িয়ে গেছে।","solution":["Motor parameter পরীক্ষা করুন।","Counterweight load পরীক্ষা করুন।","MOT-এর power class motor current-এর জন্য উপযুক্ত কি না পরীক্ষা করুন।","Car-এর চলাচলে কোনো আটকে যাওয়া নেই তা নিশ্চিত করুন।","Brake সম্পূর্ণ খোলা আছে কি না নিশ্চিত করুন।"]}'::jsonb),
('mot-er80','{"description":"Current ক্রমাগত motor limit-এর কাছাকাছি ছিল।","conditions":"Motor current “Nominal motor current” [P0159] ও “Motor overcurrent limit” [P0429] parameter-দ্বয়ের গুণফলের চেয়ে 6 সেকেন্ড ধরে বেশি থাকলে এই error দেওয়া হয়।","solution":["Motor parameter পরীক্ষা করুন।","Counterweight load পরীক্ষা করুন।","MOT-এর power class motor current-এর জন্য উপযুক্ত কি না পরীক্ষা করুন।","Car-এর চলাচলে কোনো আটকে যাওয়া নেই তা নিশ্চিত করুন।","Brake সম্পূর্ণ খোলা আছে কি না নিশ্চিত করুন।"]}'::jsonb),
('mot-er81','{"description":"Group identity conflict error।","conditions":"“Group identity” [P0086] parameter-এ নির্ধারিত group-এর MOT identity-গুলোর মধ্যে conflict থাকলে এই error হয়।","solution":["System-এর সব device-এর [P0086] parameter-এ আলাদা identity নম্বর আছে কি না পরীক্ষা করুন এবং দুই বা ততোধিক device-এর ID এক হলে বদলে দিন।"]}'::jsonb),
('mot-er82','{"description":"Group-এর সব lift-এর stop সংখ্যা সমান হতে হবে।","conditions":"System-এর (group control) কোনো elevator-এর “Number of floors” [P0002] parameter আলাদাভাবে সেট করা থাকলে এই error দেওয়া হয়।","solution":["Group-এর সব elevator-এ [P0002] parameter একই সেট করা আছে কি না নিশ্চিত করুন। নিচের এবং/অথবা উপরের অনুপস্থিত ফ্লোর “Bottom missing floors” [P0087] ও “Top missing floors” [P0088] parameter-এ সেট করতে হবে।"]}'::jsonb),
('mot-er83','{"description":"APRE unlock করা যায়নি।","conditions":"“Over speed governor monitoring” [P0788] parameter active থাকলে এবং brake খোলার পর 3 সেকেন্ডের মধ্যে “(APRI) APRE monitoring” input signal “0” অবস্থায় না এলে এই error দেওয়া হয়।","solution":["Over speed governor system ও ApRe card পরীক্ষা করুন।","যে input-এ (APRI) signal এবং যে output-এ (APRO) signal নির্ধারিত সেগুলো পরীক্ষা করুন। Signal গুলো program করা এবং wiring করা আছে কি না নিশ্চিত করুন।","Over speed governor ব্যবহার না করলে “Over speed governor monitoring” [P0788] parameter “No monitoring” সেট করুন।","Note (নোট): এটি একটি permanent error। “System Tools” menu-তে “Clear permanent error” সিলেক্ট করে এই error-এর স্থায়িত্ব মুছতে হয়।"]}'::jsonb),
('mot-er84','{"description":"APRE lock করা যায়নি।","conditions":"“Over speed governor monitoring” [P0788] parameter active থাকলে এবং output signal “(RP) Main contactor” ও “(APRO) APRE activation” “0” অবস্থায় থাকার পর “Speed governor locking time” [P0804] parameter-এর সময় পার হয়ে গেলেও “(APRI) APRE monitoring” input “1” অবস্থায় না এলে এই error দেওয়া হয়।","solution":["Over speed governor system ও ApRe card পরীক্ষা করুন।","যে input-এ (APRI) signal এবং যে output-এ (APRO) signal নির্ধারিত সেগুলো পরীক্ষা করুন। Signal গুলো program করা এবং wiring করা আছে কি না নিশ্চিত করুন।","Over speed governor ব্যবহার না করলে “Over speed governor monitoring” [P0788] parameter “No monitoring” সেট করুন।","Note (নোট): এটি একটি permanent error। “System Tools” menu-তে “Clear permanent error” সিলেক্ট করে এই error-এর স্থায়িত্ব মুছতে হয়।"]}'::jsonb),
('mot-er85','{"description":"Encoder reference error।","conditions":"“Encoder coupling type” [P0868] parameter “Indirect incremental encoder” সেট থাকলে এবং angle correction ratio 120 degree (magnetic angle) ছাড়ালে এই error হয়।","solution":["Encoder-এর সংযোগ পরীক্ষা করুন। Encoder-এর grounding সংযুক্ত আছে কি না নিশ্চিত করুন।","Encoder-এর mechanical coupling পরীক্ষা করুন। Encoder wheel slip করতে পারে।","Z channel থেকে পাওয়া reference signal সঠিক কি না পরীক্ষা করুন।"]}'::jsonb),
('mot-er86','{"description":"UCM শনাক্ত হয়েছে।","conditions":"Door bridge করা অবস্থায় signal 140 বা 130-এর একটি “0” (door খোলা) হলে অথবা ML1-ML2 signal-এর একটি “0” (door zone-এর বাইরে) হলে এই error হয়।","solution":["ML1 ও ML2 magnetic switch-এর supply পরীক্ষা করুন।","Pre-opening ও re-levelling (ফ্লোরের সাথে car পুনরায় সমান করা) function বন্ধ করুন।","Note (নোট): এটি একটি permanent error। “System Tools” menu-তে “Clear permanent error” সিলেক্ট করে এই error-এর স্থায়িত্ব মুছতে হয়।"]}'::jsonb),
('mot-er87','{"description":"Re-level zone-এর বাইরে।","conditions":"“Releveling (ফ্লোরের সাথে car পুনরায় সমান করা) function” [P0075] parameter “Releveling using 141-142 signals” সেট থাকলে: car ফ্লোরে থাকা অবস্থায় “(141) Relevel down trigger” ও “(142) Relevel up trigger” signal input “0” হলে এই error হয়। “Releveling function” [P0075] parameter “With LiftSense” সেট থাকলে: car ফ্লোরে থাকা অবস্থায় LiftSense থেকে পড়া slip value +7 ও -7 cm-এর মধ্যে না থাকলে এই error হয়। LiftSense দিয়ে releveling হলেও যদি releveling ভুল direction-এ হয় (car উপরে সরলে up direction-এ, নিচে সরলে down direction-এ releveling হওয়ার কথা), তাহলে “Manyeto sensor orientation” [P0823] parameter-এর মান বদলান।","solution":["Magnetic switch পরীক্ষা করুন। Magnetic switch অস্থিরভাবে কাজ করলে এই error আসতে পারে।","Releveling function-এ সমস্যা থাকলে বা এটি ব্যবহারের অনুপযোগী হলে pre-opening ও re-levelling function বন্ধ করুন।","Note (নোট): এটি একটি permanent error। “System Tools” menu-তে “Clear permanent error” সিলেক্ট করে এই error-এর স্থায়িত্ব মুছতে হয়।"]}'::jsonb),
('mot-er89','{"description":"Start-এর সময় car ধরে রাখা যায়নি।","conditions":"চলা শুরুর সময় rotor এক-চতুর্থাংশ পাকের (quarter-turn) বেশি ঘুরলে এই error দেয়।","solution":["Anti-Rollback PID gain (KP ও KD parameter) সামঞ্জস্য করুন।"]}'::jsonb),
('mot-er90','{"description":"Pre-opening-এর সময় over speed।","conditions":"Door bridge করা অবস্থায় car speed “Over speed error limit on preopening” [P0813] parameter-এ সেট করা মান ছাড়ালে এই error দেওয়া হয়।","solution":["[P0813] parameter-এর মান খুব কম দেওয়া হলে এই error হতে পারে।","Door pre-opening-এর সময় encoder-এ electromagnetic noise আসছে না তা নিশ্চিত করুন।"]}'::jsonb),
('mot-er91','{"description":"Shaft খুব লম্বা।","conditions":"Shaft copying-এর সময় shaft ভুলভাবে learn হলে এই error হয়। Motor speed ভুল সেট করা হলে, shaft-এর কোনো door zone magnet-এর দৈর্ঘ্য ভুল হলে অথবা flag length parameter ভুল হলে এই error দেওয়া হবে।","solution":["পরিবর্তন করার পর shaft copy process আবার করতে হবে।"]}'::jsonb),
('mot-er92','{"description":"Position tracking error।","conditions":"বিশেষ করে “incremental encoder” ব্যবহৃত KONE motor-এ error rate খুব বেশি হলে এই error দেওয়া হয়।","solution":["এই error-এর trigger sensitivity “Pos. tracking error sensitivity” [P1085] parameter দিয়ে সেট করা যায়।","Standard geared বা gearless motor-এ এই error হলে “Pos. tracking error sensitivity” [P1085] parameter “Off” সিলেক্ট করা যায়।"]}'::jsonb),
('mot-er93','{"description":"Maintenance time ছাড়িয়েছে।","conditions":"System clock “Maintenance time” [P1006] parameter-এ সেট করা সময় ছাড়িয়ে গেলে system এই error দেয় এবং service-এর বাইরে চলে যায়।","solution":["“Maintenance time” [P1006] parameter active হওয়ার জন্য আগে “Maintenance time control” [P1005] parameter “On” সেট করতে হবে।","Error active হওয়ার পর এটি মুছতে [P1006]-এ maintenance time পরবর্তী কোনো সময়ে সেট করতে হবে অথবা [P1005] parameter “Off” সেট করতে হবে।"]}'::jsonb),
('mot-er94','{"description":"Car light fuse পুড়ে গেছে।","conditions":"“Behavior when car light fuse is blown” [P0799] parameter “Only inspection” সেট থাকলে এবং MOT 3 phase-এর উপস্থিতি শনাক্ত করলেও IBC board-এর terminal 1-এ 220VAC voltage না থাকলে এবং system inspection mode-এ না থাকলে এই error হবে।","solution":["IBC board-এর input terminal 1-এ কেন 220VAC voltage নেই তা পরীক্ষা করুন।"]}'::jsonb),
('mot-er95','{"description":"Manual rescue (SEV key)।","conditions":"“Acceptance test tools” [P0810] parameter “Off” থাকা অবস্থায় “(MEM) Manual-evacuation mode switch” signal active হলে এই error দেওয়া হয়। Main power চলে যাওয়ার পর manual evacuation switch ব্যবহার করা হয় বলে এই error একটি সতর্কবার্তা হিসেবে দেওয়া হয়।","solution":["“Acceptance test tools” শুধু test-এর সময় active করা উচিত।","“SEV” switch-এর প্রয়োজন না থাকলে সেটি বন্ধ আছে কি না নিশ্চিত করুন।"]}'::jsonb),
('mot-er96','{"description":"Test-এ UPS (ব্যাকআপ বিদ্যুৎ ব্যবস্থা) ব্যর্থ হয়েছে।","conditions":"UPS test সফলভাবে সম্পন্ন না হলে এই error হবে।","solution":["Battery পরীক্ষা করুন।","UPS battery charge terminal পরীক্ষা করুন।","Note (নোট): এটি একটি permanent error। “System Tools” menu-তে “Clear permanent error” সিলেক্ট করে এই error-এর স্থায়িত্ব মুছতে হয়।"]}'::jsonb),
('mot-er97','{"description":"Direction change limit-এ পৌঁছেছে।","conditions":"“Direction change count limit” [P0964] parameter “0” ছাড়া অন্য কোনো মানে সেট থাকলে এবং direction change counter এই মানে পৌঁছালে, ফ্লোরে প্রথম থামার পর এই error হয়।","solution":["এই function সাধারণত plastic-coated rope তার duty cycle-এ পৌঁছানোর পর ব্যবহার আটকাতে ব্যবহার করা হয়। Rope বদলানোর পর [P0964] parameter উপযুক্ত মানে বাড়াতে হবে।","Rope plastic-coated না হলে এই মান “0” সেট করতে হবে।","Rope বদলানোর পর “Direction change count limit” মান আবার সেট করলে মনে রাখতে হবে, নতুন মান আগের মানের সাথে যোগ হবে।","Note (নোট): এটি একটি permanent error। “System Tools” menu-তে “Clear permanent error” সিলেক্ট করে এই error-এর স্থায়িত্ব মুছতে হয়।"]}'::jsonb),
('mot-er98','{"description":"একটি critical device offline।","conditions":"Normal operation-এর সময় critical signal হিসেবে programmable input নির্ধারিত কোনো peripheral device থেকে CANbus সংযোগ (communication) কেটে গেলে এই error হয়। উদাহরণস্বরূপ, photocell input (FSLA) কোনো একটি IBC board-এর programmable input-এ program করা থাকলে এবং main controller সেই IBC board-এর সাথে communicate করতে না পারলে normal operation-এর সময় এই error দেওয়া হয়।","solution":["এই error code EN 81-20 standard অনুযায়ী যোগ করা হয়েছে। Installation-এর সময় এই error এড়াতে “Operation mode” [P0292] parameter “Installation mode” সেট করতে হবে।","Critical signal হলো সেই signal গুলো, যেগুলো programmable input menu-তে লাল রঙে দেখানো হয়। Critical signal গুলো: 869, 870, 868, FSLHA, FSLA, K19A, BYP, FSLHB, FSLB, K19B, SPR*, FES1, FES2, FFKL, FRES, FFKC, PAN, DEP, FD0A, FD0B, FDL*, U36*।","Critical signal গুলো কোথায় program করা আছে তা “Info” menu-র “Inputs/Outputs by Function” screen থেকে দেখা যায়।","এই error-এর কারণ বিশ্লেষণ ছাড়াই system-কে এই error না দেখাতে চাইলে “Critical device monitoring” [P1035] parameter “Off” সেট করুন; এতে protection monitoring বন্ধ হয়ে যায় এবং এই error আর দেওয়া হয় না।","সম্ভবত কোনো critical signal কোনো peripheral device-এর input-এ নির্ধারিত আছে, কিন্তু হয় সেই peripheral device সংযুক্ত করা হয়নি, অথবা সংযুক্ত করার পর update করা হয়নি। Firmware update করুন।"]}'::jsonb),
('mot-er99','{"description":"Rope slip correction error।","conditions":"“Rope slip correction” [P1033] parameter active থাকলে MOT-এর door zone correction movement সর্বোচ্চ 100 cm পর্যন্ত হতে পারে। 100 cm চলার পরও door zone পাওয়া না গেলে এই error দেওয়া হয়। এই parameter active করার পর MOT rope slip করার সম্ভাবনা বিবেচনা করে এবং door zone পার হওয়ার সময় encoder থেকে পাওয়া তথ্য অনুযায়ী দূরত্বের error সংশোধন করে। MOT সংশোধন করলে MOT-এর buzzer থেকে শব্দ পাওয়া যায় এবং সংশোধন হয়েছে বোঝাতে MOT-এর “floor level” LED জ্বলতে-নিভতে থাকে।","solution":["Rope-এর slip পরীক্ষা করুন।"]}'::jsonb),
('mot-er100','{"description":"External Perm. Error-1 (Recall ছাড়া)।","conditions":"“(XPE1) Ext. Perm. Error-1(Except/inspection recall)” input signal active হলে এই error হয়।","solution":["সংশ্লিষ্ট input-এর সংযোগ পরীক্ষা করুন।","এই input active হয়ে এই error এলেও Inspection বা Recall mode-এ car চালানো সম্ভব।","Note (নোট): এটি একটি permanent error। “System Tools” menu-তে “Clear permanent error” সিলেক্ট করে এই error-এর স্থায়িত্ব মুছতে হয়।"]}'::jsonb),
('mot-er101','{"description":"Insp. /Recall terminal সংযোগ ভুল।","conditions":"কোনো inspection/recall key inspection position-এ নেওয়ার পর up/down button না চাপা থাকলেও signal 120 active থাকলে এই error দেওয়া হয়।","solution":["এই error বোঝায় যে inspection/recall terminal circuit-এর wiring-এ সমস্যা আছে। Wiring পরীক্ষা করুন।","System inspection mode-এ থাকলে safety circuit signal 120 কেটে যাচ্ছে কি না নিশ্চিত করুন।","“Operation mode” [P0292] parameter “Normal operation” সেট থাকলে এই protection সবসময় active থাকে। Parameter “Installation mode” সেট থাকলে এবং “Bridged hand-terminal detection” [P1127] parameter “Disabled (Warning: Danger of death!!!)” সেট থাকলে এই protection active থাকবে না এবং এই error হবে না।"]}'::jsonb),
('mot-er102','{"description":"EN signal কাটেনি।","conditions":"(RP) (main contactor) relay off (power নেই) থাকলে বা (140P) signal off থাকলে এবং (EN) signal তখনও active থাকলে এই error হয়। অর্থাৎ contactor drop করেছে, কিন্তু (EN) signal ক্রমাগত active। Normal operation-এ elevator চলার সময় (EN) signal active হয় এবং elevator স্থির থাকলে (EN) signal off থাকে।","solution":["Contactor de-energized থাকা অবস্থায় যে input-এ (EN) signal program করা আছে সেটি কেন active হলো তা পরীক্ষা করুন।","(EN) signal-এ 100 (24VDC) signal যে circuit দিয়ে যায়, সেটি main contactor-এর NO contact দিয়ে যায়। Main contactor ঠিকমতো কাজ করছে কি না নিশ্চিত করুন এবং contact আটকে যাওয়ার সম্ভাবনা পরীক্ষা করুন।","(EN) input ও 100 (24VDC)-এর মধ্যে কোনো bridge নেই তা নিশ্চিত করুন।"]}'::jsonb),
('mot-er104','{"description":"140 ON এবং 140P OFF।","conditions":"Hardware error।","solution":["MOT-এ update-এর সর্বশেষ firmware version আছে কি না নিশ্চিত করুন।"]}'::jsonb),
('mot-er108','{"description":"SD card error। কোনো SD card নেই।","conditions":"Arpass function active থাকলে এবং কাজের ধরন “With magnetic card” সিলেক্ট করা থাকলে device-এ SD card থাকতে হবে।","solution":["আপনার device-এ SD card লাগান।"]}'::jsonb),
('mot-er110','{"description":"IPM error। Drive supply under voltage। Supply voltage 19 VDC-এর নিচে নেমে গেছে।","conditions":"24 VDC limit-এর নিচে নামলে অথবা SMPS-এ short circuit থাকলে এই error দেওয়া হয়।","solution":["24 VDC supply পরীক্ষা করতে হবে।"]}'::jsonb),
('mot-er111','{"description":"IPM error। Transistor short-circuit।","conditions":"Travel-এর সময় safety circuit কেটে যেতে পারে, অথবা কোনো কারণে contactor drop করতে পারে।","solution":["নির্দিষ্ট কোনো ফ্লোরে এই error হলে সেই landing door contact পরীক্ষা করুন।","বিভিন্ন ফ্লোরে এই error হলে car door contact পরীক্ষা করুন।","Contactor ত্রুটিপূর্ণ হওয়ার সম্ভাবনা থাকলে motor cable সরাসরি MOT-এর “U, V, W” output terminal-এ সংযুক্ত করে (panel bypass করে) system-এর কাজ পরীক্ষা করুন। এ ক্ষেত্রে error না এলে contactor ও সংযোগ পরীক্ষা করুন।"]}'::jsonb),
('mot-er112','{"description":"IPM error। IPM overheat হয়েছে।","conditions":"IPM temperature 120 degree-এর উপরে গেলে এই error দেওয়া হয়। এছাড়া 24 VDC voltage কমে গেলেও এই error আসতে পারে।","solution":["Motor অনুযায়ী device সঠিকভাবে নির্বাচন করা হয়েছে কি না নিশ্চিত করুন।"]}'::jsonb),
('mot-er113','{"description":"Movement-এর সময় 130 OFF।","conditions":"Movement-এর সময় signal 130 কেটে গেলে এই error দেখা যায়।","solution":["Door semi-automatic হলে landing door contact পরীক্ষা করতে হবে। Error log থেকে যে landing door contact-এ error হয়েছে সেটি পরীক্ষা করতে হবে।","Door full automatic হলে [P1029] “Door safety connections” parameter যেভাবে সেট করা আছে সেই অনুযায়ী:","“EN81-20 compatible” হলে 120-130-এর মধ্যে একটি bridge থাকতে হবে। এই bridge পরীক্ষা করুন।","“EN81-1 compatible” হলে landing door contact 120-130-এর মধ্যে সংযুক্ত থাকতে হবে। সংযোগ সেই অনুযায়ী করতে হবে। Error log থেকে যে landing door contact-এ error হয়েছে সেটি পরীক্ষা করতে হবে।"]}'::jsonb),
('mot-er114','{"description":"Movement-এর সময় 140P ক্ষণিকের জন্য বিচ্ছিন্ন হয়েছে।","conditions":"Movement-এর সময় signal 140P বিচ্ছিন্ন হলে এই error দেখা যায়।","solution":["DBR board ব্যবহার করা হলে নিচের parameter সেই অনুযায়ী সেট করতে হবে: Device settings > DBR card functions > Door early opening card: installed।","MOT-এর ভেতরের DBR board পরীক্ষা করতে হবে; ribbon cable বা wiring-এ সমস্যা থাকতে পারে।","140 থেকে 140P-এ একটি bridge দেওয়া যায় এবং (P0069) Door safety circuit bridging board: not installed সেট করতে হবে। Er114 চলে গেলে বোঝা যাবে DBR board ত্রুটিপূর্ণ।"]}'::jsonb),
('nice-err02','{"description":"Acceleration-এর সময় overcurrent","solution":["কারণ: Main circuit output ground হয়ে গেছে অথবা short circuit হয়েছে। | Motor cable ও PE cable (প্রোটেকটিভ আর্থ ক্যাবল) ভুলভাবে সংযুক্ত আছে কি না দেখুন। Shorting PMSM (স্থায়ী চুম্বক সিঙ্ক্রোনাস মোটর) stator contactor (বৈদ্যুতিক সুইচিং ডিভাইস)-এর কারণে controller output side-এ short circuit হচ্ছে কি না দেখুন। Motor cable-এর jacket (বাইরের আবরণ) ক্ষতিগ্রস্ত কি না দেখুন।","কারণ: Motor auto-tuning (স্বয়ংক্রিয়ভাবে মোটরের বৈশিষ্ট্য শনাক্তকরণ) ঠিকভাবে করা হয়নি। | Motor nameplate অনুযায়ী motor parameter (সেটিং মান) সঠিকভাবে সেট করুন এবং আবার motor auto-tuning করুন।","কারণ: Encoder signal ভুল বা অস্বাভাবিক। | Encoder PPR (pulses per revolution) সঠিকভাবে সেট করা আছে কি না দেখুন। Encoder signal-এ interference (ব্যাঘাত) হচ্ছে কি না, encoder (ঘূর্ণন অবস্থান সেন্সর) cable আলাদা duct দিয়ে গেছে কি না, cable বেশি লম্বা কি না এবং shield শুধু এক প্রান্তে earth করা আছে কি না দেখুন। Encoder নির্ভরযোগ্যভাবে লাগানো আছে কি না এবং ঘূর্ণায়মান shaft motor shaft-এর সাথে ঠিকমতো যুক্ত আছে কি না দেখুন — normal-speed running-এর সময় encoder স্থির (stable) আছে কি না লক্ষ্য করে বুঝুন। Encoder wiring সঠিক কি না দেখুন। Asynchronous motor-এর ক্ষেত্রে SVC (সেন্সরলেস ভেক্টর কন্ট্রোল) চালিয়ে current তুলনা করে encoder ঠিকমতো কাজ করছে কি না বিচার করুন।","কারণ: Motor phase sequence ভুল। | Motor-এর UVW cable-এর যেকোনো দুটি অদলবদল করুন।","কারণ: Acceleration rate খুব ছোট। | Acceleration rate কমান।"]}'::jsonb),
('nice-err03','{"description":"Deceleration-এর সময় overcurrent","solution":["কারণ: Main circuit output ground হয়ে গেছে অথবা short circuit হয়েছে। | Motor cable ও PE cable ভুলভাবে সংযুক্ত আছে কি না দেখুন। Shorting PMSM stator contactor-এর কারণে controller output side-এ short circuit হচ্ছে কি না দেখুন। Motor cable-এর jacket (বাইরের আবরণ) ক্ষতিগ্রস্ত কি না দেখুন।","কারণ: Motor auto-tuning ঠিকভাবে করা হয়নি। | Motor nameplate অনুযায়ী motor parameter সঠিকভাবে সেট করুন এবং আবার motor auto-tuning করুন।","কারণ: Encoder signal ভুল বা অস্বাভাবিক। | Encoder PPR (pulses per revolution) সঠিকভাবে সেট করা আছে কি না দেখুন। Encoder signal-এ interference (ব্যাঘাত) হচ্ছে কি না, encoder cable আলাদা duct দিয়ে গেছে কি না, cable বেশি লম্বা কি না এবং shield শুধু এক প্রান্তে earth করা আছে কি না দেখুন। Encoder নির্ভরযোগ্যভাবে লাগানো আছে কি না এবং ঘূর্ণায়মান shaft motor shaft-এর সাথে ঠিকমতো যুক্ত আছে কি না দেখুন — normal-speed running-এর সময় encoder স্থির (stable) আছে কি না লক্ষ্য করে বুঝুন। Encoder wiring সঠিক কি না দেখুন। Asynchronous motor-এর ক্ষেত্রে SVC চালিয়ে current তুলনা করে encoder ঠিকমতো কাজ করছে কি না বিচার করুন।","কারণ: Deceleration curve খুব steep (খাড়া)। | Deceleration rate কমান।"]}'::jsonb),
('nice-err04','{"description":"Constant speed-এ overcurrent","solution":["কারণ: Main circuit output ground হয়ে গেছে অথবা short circuit হয়েছে। | Motor cable ও PE cable ভুলভাবে সংযুক্ত আছে কি না দেখুন। Shorting PMSM stator contactor-এর কারণে controller output side-এ short circuit হচ্ছে কি না দেখুন। Motor cable-এর jacket (বাইরের আবরণ) ক্ষতিগ্রস্ত কি না দেখুন।","কারণ: Motor auto-tuning ঠিকভাবে করা হয়নি। | Motor nameplate অনুযায়ী motor parameter সঠিকভাবে সেট করুন এবং আবার motor auto-tuning করুন।","কারণ: Encoder signal ভুল বা অস্বাভাবিক। | Encoder PPR (pulses per revolution) সঠিকভাবে সেট করা আছে কি না দেখুন। Encoder signal-এ interference (ব্যাঘাত) হচ্ছে কি না, encoder cable আলাদা duct দিয়ে গেছে কি না, cable বেশি লম্বা কি না এবং shield শুধু এক প্রান্তে earth করা আছে কি না দেখুন। Encoder নির্ভরযোগ্যভাবে লাগানো আছে কি না এবং ঘূর্ণায়মান shaft motor shaft-এর সাথে ঠিকমতো যুক্ত আছে কি না দেখুন — normal-speed running-এর সময় encoder স্থির (stable) আছে কি না লক্ষ্য করে বুঝুন। Encoder wiring সঠিক কি না দেখুন। Asynchronous motor-এর ক্ষেত্রে SVC চালিয়ে current তুলনা করে encoder ঠিকমতো কাজ করছে কি না বিচার করুন।"]}'::jsonb),
('nice-err05','{"description":"Acceleration-এর সময় overvoltage","solution":["কারণ: Input voltage খুব বেশি। | Input voltage খুব বেশি কি না দেখুন। Bus voltage খুব বেশি কি না লক্ষ্য করুন (normal: 380 V input-এর জন্য 540 থেকে 580 V)।","কারণ: Braking resistor-এর resistance অতিরিক্ত বেশি, অথবা braking unit ফেইল করেছে। | Balance coefficient পরীক্ষা করুন। Running-এর সময় bus voltage (ডিসি লিংক ভোল্টেজ) খুব দ্রুত বাড়ছে কি না দেখুন। যদি বাড়ে, তাহলে braking resistor (ব্রেকিং রোধ) কাজ করছে না অথবা এর model উপযুক্ত নয়: a. Braking resistor-এর সাথে সংযুক্ত cable ক্ষতিগ্রস্ত কি না, copper wire ground স্পর্শ করছে কি না এবং সংযোগ নির্ভরযোগ্য কি না দেখুন। b. Recommendation অনুযায়ী resistance উপযুক্ত কি না দেখুন এবং উপযুক্ত braking resistor বেছে নিন। Braking resistor-এর resistance ঠিক আছে, কিন্তু লিফট target speed-এ পৌঁছালেই প্রতিবার overvoltage হচ্ছে — এ ক্ষেত্রে F2-01 বা F2-04-এর মান কমান, যাতে curve following error কমে এবং system overshoot-এর কারণে overvoltage না হয়।","কারণ: Acceleration rate খুব ছোট। | Acceleration rate কমান।"]}'::jsonb),
('nice-err06','{"description":"Deceleration-এর সময় overvoltage","solution":["কারণ: Input voltage খুব বেশি। | Input voltage খুব বেশি কি না দেখুন। Bus voltage খুব বেশি কি না লক্ষ্য করুন (normal: 380 V input-এর জন্য 540 থেকে 580 V)।","কারণ: Braking resistor-এর resistance অতিরিক্ত বেশি, অথবা braking unit ফেইল করেছে। | Balance coefficient পরীক্ষা করুন। Running-এর সময় bus voltage খুব দ্রুত বাড়ছে কি না দেখুন। যদি বাড়ে, তাহলে braking resistor কাজ করছে না অথবা এর model উপযুক্ত নয়: a. Braking resistor-এর সাথে সংযুক্ত cable ক্ষতিগ্রস্ত কি না, copper wire ground স্পর্শ করছে কি না এবং সংযোগ নির্ভরযোগ্য কি না দেখুন। b. Recommendation অনুযায়ী resistance উপযুক্ত কি না দেখুন এবং উপযুক্ত braking resistor বেছে নিন। Braking resistor-এর resistance ঠিক আছে, কিন্তু লিফট target speed-এ পৌঁছালেই প্রতিবার overvoltage হচ্ছে — এ ক্ষেত্রে F2-01 বা F2-04-এর মান কমান, যাতে curve following error কমে এবং system overshoot-এর কারণে overvoltage না হয়।","কারণ: Deceleration rate খুব ছোট। | Deceleration rate কমান।"]}'::jsonb),
('nice-err07','{"description":"Constant speed-এ overvoltage","solution":["কারণ: Input voltage খুব বেশি। | Input voltage খুব বেশি কি না দেখুন। Bus voltage খুব বেশি কি না লক্ষ্য করুন (normal: 380 V input-এর জন্য 540 থেকে 580 V)।","কারণ: Braking resistor-এর resistance অতিরিক্ত বেশি, অথবা braking unit ফেইল করেছে। | Balance coefficient পরীক্ষা করুন। Running-এর সময় bus voltage খুব দ্রুত বাড়ছে কি না দেখুন। যদি বাড়ে, তাহলে braking resistor কাজ করছে না অথবা এর model উপযুক্ত নয়: a. Braking resistor-এর সাথে সংযুক্ত cable ক্ষতিগ্রস্ত কি না, copper wire ground স্পর্শ করছে কি না এবং সংযোগ নির্ভরযোগ্য কি না দেখুন। b. Recommendation অনুযায়ী resistance উপযুক্ত কি না দেখুন এবং উপযুক্ত braking resistor বেছে নিন। Braking resistor-এর resistance ঠিক আছে, কিন্তু লিফট target speed-এ পৌঁছালেই প্রতিবার overvoltage হচ্ছে — এ ক্ষেত্রে F2-01 বা F2-04-এর মান কমান, যাতে curve following error কমে এবং system overshoot-এর কারণে overvoltage না হয়।"]}'::jsonb),
('nice-err08','{"description":"Maintenance notification period শেষ হয়েছে","solution":["কারণ: নির্ধারিত notification period-এর মধ্যে লিফটের maintenance করা হয়নি। | লিফট power-off করে maintenance করুন। F9-13 কে 0 সেট করে maintenance notification ফাংশন বন্ধ করুন। R&I team-এর সাথে যোগাযোগ করুন।"]}'::jsonb),
('nice-err09','{"description":"Under voltage","solution":["কারণ: Input power supply-তে মুহূর্তের (instantaneous) power failure হয়েছে। | Running-এর সময় power চলে যায় কি না দেখুন। সব power input cable-এর wiring শক্তভাবে সংযুক্ত কি না দেখুন।","কারণ: Input voltage খুব কম। | বাইরের power voltage খুব কম কি না দেখুন।","কারণ: Drive control board ফেইল করেছে। | R&I team-এর সাথে যোগাযোগ করুন।"]}'::jsonb),
('nice-err10','{"description":"Controller overload","solution":["কারণ: Mechanical resistance খুব বেশি। | Brake release হয়েছে কি না এবং brake power supply normal কি না দেখুন। Guide shoe খুব টাইট কি না দেখুন।","কারণ: Balance coefficient ঠিক নেই। | Balance coefficient সঠিক কি না দেখুন।","কারণ: Encoder feedback signal অস্বাভাবিক। | Encoder feedback signal ও parameter সেটিং সঠিক কি না, এবং PMSM-এর জন্য encoder-এর initial angle সঠিক কি না দেখুন।","কারণ: Motor auto-tuning ঠিকভাবে করা হয়নি (এ ক্ষেত্রে লিফটের running current normal-এর চেয়ে বেশি হয়)। | Motor parameter সেটিং পরীক্ষা করে আবার motor auto-tuning করুন। Slip experiment চালানোর সময় এই fault এলে F3-24-এ সেট করা ফাংশন ব্যবহার করে slip experiment করুন।","কারণ: Motor phase sequence ভুল। | Motor-এর UVW cable-এর যেকোনো দুই phase অদলবদল করুন।","কারণ: ছোট power class-এর controller ব্যবহার করা হয়েছে। | Car-এ load ছাড়া constant speed running-এর সময় current AC drive-এর rated current-এর উপরে চলে যায়।"]}'::jsonb),
('nice-err11','{"description":"Motor overload","solution":["কারণ: Mechanical resistance খুব বেশি। | Brake release হয়েছে কি না এবং brake power supply normal কি না দেখুন। Guide shoe খুব টাইট কি না দেখুন।","কারণ: Balance coefficient ঠিক নেই। | Balance coefficient সঠিক কি না দেখুন।","কারণ: Motor auto-tuning ঠিকভাবে করা হয়নি (এ ক্ষেত্রে লিফটের running current normal-এর চেয়ে বেশি হয়)। | Motor parameter সেটিং পরীক্ষা করে আবার motor auto-tuning করুন। Slip experiment চালানোর সময় এই fault এলে F3-24-এ সেট করা ফাংশন ব্যবহার করে slip experiment করুন।","কারণ: Motor phase sequence ভুল। | Motor-এর UVW cable-এর যেকোনো দুই phase অদলবদল করুন।","কারণ: ছোট power class-এর motor ব্যবহার করা হয়েছে। | Car-এ load ছাড়া constant speed running-এর সময় current motor-এর rated current-এর উপরে চলে যায়।"]}'::jsonb),
('nice-err12','{"description":"Power supply phase loss","solution":["কারণ: Power input-এর phase গুলো symmetric (সমান) নয়। | Three-phase power supply-র কোনো phase হারিয়ে গেছে কি না দেখুন। Power supply-র তিনটি phase balanced কি না দেখুন। Power voltage normal কি না দেখুন এবং voltage ঠিক করুন। 220 V model-এর ক্ষেত্রে এই fault-এর detection বাতিল করতে FC-01-এর bit 14 কে 1 সেট করুন।","কারণ: Drive control board ফেইল করেছে। | সরাসরি আমাদের বা আমাদের agent-এর সাথে যোগাযোগ করুন।"]}'::jsonb),
('nice-err13','{"description":"Power output phase loss","solution":["কারণ: Main circuit-এর output wiring ঢিলা। | Motor wiring শক্তভাবে সংযুক্ত কি না দেখুন। Output side-এর RUN contactor normal কি না দেখুন।","কারণ: Motor ক্ষতিগ্রস্ত। | Motor-এর fault দূর করুন।"]}'::jsonb),
('nice-err14','{"description":"IGBT (পাওয়ার সুইচিং সেমিকন্ডাক্টর) overheat","solution":["কারণ: Ambient temperature (পরিবেশের তাপমাত্রা) খুব বেশি। | Ambient temperature কমান।","কারণ: Fan ক্ষতিগ্রস্ত। | ক্ষতিগ্রস্ত fan বদলান।","কারণ: Air filter আটকে গেছে। | Air filter পরিষ্কার করুন। Controller-এর installation clearance (চারপাশের ফাঁকা জায়গা) প্রয়োজনীয় মান পূরণ করছে কি না দেখুন।"]}'::jsonb),
('nice-err15','{"description":"Output abnormal","subcodes":[{"code":"1","description":"Braking resistor short-circuited।","solution":["Braking resistor ও braking unit-এর wiring সঠিক এবং short circuit ছাড়া কি না দেখুন।","Main contactor ঠিকমতো কাজ করছে কি না এবং arc বা stuck (আটকে যাওয়া) সমস্যা আছে কি না দেখুন।"]},{"code":"2","description":"Braking IGBT short-circuited।","solution":["R&I team-এর সাথে যোগাযোগ করুন।"]}]}'::jsonb),
